-- Canonical summary edits only. Stable IDs, access tiers, links and rights metadata stay intact.
-- Reviewed against a full privileged backup; refuse to overwrite intervening CMS edits.
do $edit$
declare edits jsonb := '[{"id":"kb_754","title":"限定合理性","old_summary":"人は情報・時間・処理能力の制約の中で、十分に満足できる選択肢を見つけて判断するという考え方。","new_summary":"人は情報、時間、計算能力の制約下で完全最適化ではなく、満足できる選択肢を探すという意思決定観。現場では探索の停止基準と重要情報を先に決める助けになる。","old_note":null,"new_note":null},{"id":"kb_756","title":"期待効用理論","old_summary":"各結果から得られる満足度を、その結果が起こる確率で重みづけし、合計が最大になる選択肢を選ぶ意思決定モデル。","new_summary":"金額そのものではなく結果から得る効用を確率加重して選択を説明する規範理論。リスク態度を表せる一方、アレのパラドックスなど実際の選択との体系的なずれがある。","old_note":null,"new_note":null},{"id":"kb_884","title":"過剰正当化効果","old_summary":"楽しんでいた活動に外的報酬を与えると、報酬がなくなった後の自発的な関心が弱まることがある現象。報酬を予告するか、どう受け止められるかによって影響が変わる。","new_summary":"もともと楽しんでいた活動に外的な報酬の理由が加わると、報酬のない場面での自発的な関心が弱まることがある現象。原著では、予告された報酬と予告されない報酬などを比べた。すべての報酬が意欲を損なうわけではなく、報酬の予期、伝え方、活動の性質が重要になる。自己決定理論全体と、個別の実験現象を同義語にしない。","old_note":null,"new_note":null},{"id":"kb_899","title":"マズローの欲求階層説","old_summary":"人の欲求を、生理・安全・所属・承認・自己実現などの階層で捉える理論。満たされていない基礎的欲求が行動を動機づけると考え、複数の欲求の重なりや例外も扱う。","new_summary":"人の欲求を、生理、安全、愛と所属、承認、自己実現などの階層から理解する理論。満たされていない基礎的欲求が動機づけに関わるという視点を与える。生活や仕事の困難を本人の意欲だけへ帰さず、条件を確かめる参考になる。ただし、全員が固定の順番を通るわけではなく、原著にも例外や複数の欲求が同時に働くことへの言及がある。","old_note":null,"new_note":null},{"id":"kb_133","title":"プロスペクト理論","old_summary":"人は基準点からの得失で結果を評価し、同じ大きさの利益より損失を強く感じやすいとする意思決定理論。利益を得る場面と損失を避ける場面では、リスクへの態度も変わる。","new_summary":"人は絶対的な結果ではなく基準点からの得失で判断し、利益より損失を強く感じるという意思決定理論。同程度の確率でも、利得局面ではリスク回避、損失局面ではリスク追求へ傾きやすい反射効果を含む。","old_note":null,"new_note":null},{"id":"kb_533","title":"習慣の下限設定","old_summary":"意欲が低い日でもできる最小限の行動量を決め、習慣を続けやすくする方法。毎日の着手と、中断後の再開を容易にする。","new_summary":"意欲が低い日でも実行できる最小量をあらかじめ決め、行動の連続性を守る方法。成果の最大化ではなく、再開コストを下げて習慣の断絶を防ぐことを目的とする。","old_note":null,"new_note":null},{"id":"kb_534","title":"連続性原理","old_summary":"行動を続ける流れや、途切れても戻れる仕組みを整えることで、次の実行をしやすくする実務的な原則。","new_summary":"行動の頻度や流れを途切れさせないことが、次の実行を容易にするという実務的原則。単なる連続日数への執着ではなく、中断後もすぐ戻れる仕組みを含む。","old_note":null,"new_note":null},{"id":"kb_887","title":"ソマティック・マーカー仮説","old_summary":"経験と結びついた身体反応やその脳内表象が、選択肢への好悪を生み、意思決定を方向づけるという仮説。","new_summary":"過去の経験と結びついた身体状態の信号や、その脳内の表象が、選択肢の評価や意思決定を方向づけるという仮説。感情は合理的判断の邪魔にしかならないという見方を見直す手がかりになる。ただし、身体の感覚が常に正しい選択を教えるという主張ではない。信号と、確率や根拠を使った検討を併せて評価する必要がある。","old_note":null,"new_note":null},{"id":"kb_209","title":"ネガティブ強化","old_summary":"不快なものが取り除かれることで、その直前の行動が増える学習の仕組み。例えば、断ると催促が止まる経験は、断る行動を強める。","new_summary":"不快な刺激が取り除かれることで、その直前の行動が増える仕組み。罰ではなく、逃避や回避を強める強化である。","old_note":null,"new_note":null},{"id":"kb_735","title":"観察学習／社会的学習理論","old_summary":"他者の行動とその結果を見ることで、自分が直接経験していない行動も学べるという理論。観察への注意、記憶、実行能力、動機が学習の成立を左右する。","new_summary":"他者の行動と結果を観察し、直接経験しなくても行動を学ぶという理論。注意、保持、再生、動機づけが必要で、見ただけで必ず模倣するわけではない。","old_note":null,"new_note":null},{"id":"kb_276","title":"最大化傾向","old_summary":"選択肢を広く比較し、最も良いものを選ぼうとし続ける傾向。比較の負担や、選んだ後の後悔が増えることもある。","new_summary":"十分に良い選択ではなく、可能な限り最善の選択を探し続ける傾向。","old_note":null,"new_note":null},{"id":"kb_943","title":"フォッグ行動モデル","old_summary":"行動は、動機・実行のしやすさ・きっかけが同じ時点でそろうと起こる、と捉えるモデル。行動を小さくし、適切なタイミングに合図を置く設計に使う。","new_summary":"行動が起こるには、動機、実行のしやすさ、きっかけが同じ時点で揃うとする設計モデル。続かないときは意欲を責める前に、作業の難しさや合図の位置を調整する。例えば行動を小さくし、いつもの行動の後に置く。数式は設計の見方を表すもので、行動の発生を数値で必ず予測する法則ではない。","old_note":null,"new_note":null},{"id":"kb_944","title":"行動変容ステージモデル","old_summary":"行動を変える準備を、無関心・関心・準備・実行・維持などの段階で捉えるモデル。本人が今いる段階に合わせて、情報提供や実行支援を考える。","new_summary":"行動を変える準備を、無関心、関心、準備、実行、維持などの段階で捉えるモデル。まだ変える意図がない人と、実行後に続けたい人では支援の内容が違う。押しつける前に本人の準備や障壁を確認する。実際の変化は行き戻りがあり、あらゆる行動が同じ段階を必ず順番に通るわけではない。","old_note":null,"new_note":null},{"id":"kb_1028","title":"習慣不連続性仮説","old_summary":"引っ越しや転職などで行動の手掛かりとなる状況が変わると、古い習慣の自動的な実行が弱まり、行動を見直す機会が生まれるという仮説。通勤経路が変わったときに移動手段を選び直す場合などが例になる。","new_summary":"引っ越しや転職などで行動の手掛かりとなる状況が変わると、古い習慣の自動的な実行が弱まり、行動を見直す機会が生まれるという仮説。通勤経路が変わったときに移動手段を選び直す場合などが例になる。生活の移行期には、望む行動を実行しやすい手順や物の配置を早めに作るとよい。変化だけで良い習慣が自然に身につくわけではなく、新しい機会や支援が必要である。継続が途切れた人の意欲不足を意味しない。","old_note":null,"new_note":null},{"id":"kb_1029","title":"行動の波及効果","old_summary":"一つの行動やそれを促す介入が、直接は対象としていなかった別の行動にも影響すること。節電を始めて他の省資源行動も増える場合もあれば、良いことをした安心から別の消費が増える場合もある。","new_summary":"一つの行動やそれを促す介入が、直接は対象としていなかった別の行動にも影響すること。節電を始めて他の省資源行動も増える場合もあれば、良いことをした安心から別の消費が増える場合もある。施策の評価では狙った行動だけでなく、隣接する行動への正負の影響も確認する。二つの行動が一緒に起きたという相関だけでは波及とは言えない。モラル・ライセンシングは負の波及を説明しうる一つの機序で、全体の同義語ではない。","old_note":null,"new_note":null},{"id":"kb_1030","title":"社会規範フィードバック","old_summary":"自分の行動を、関連する集団の実際の行動や望ましい基準と比較して伝える方法。電力使用量を近い条件の世帯と比べて示すことなどが例になる。","new_summary":"自分の行動を、関連する集団の実際の行動や望ましい基準と比較して伝える方法。電力使用量を近い条件の世帯と比べて示すことなどが例になる。介入では比較対象を適切に選び、実際の分布を正確に伝える。平均より良い行動をしていた人が平均へ戻る逆効果もあるため、望ましい行動への承認を組み合わせるなど設計が必要になる。単に「皆がやっている」と圧力をかける方法ではなく、効果の方向を測定して確かめる技法である。","old_note":null,"new_note":null},{"id":"kb_1032","title":"COM-Bモデル","old_summary":"行動の成立を、能力、機会、動機の相互作用として捉えるモデル。実行しない人に意欲を求める前に、方法を知っているか、必要な場所や道具があるか、習慣や感情がどう関わるかを分けて調べる。","new_summary":"行動の成立を、能力、機会、動機の相互作用として捉えるモデル。実行しない人に意欲を求める前に、方法を知っているか、必要な場所や道具があるか、習慣や感情がどう関わるかを分けて調べる。例えば研修後に手順を使わない場合、知識不足と時間不足では支援が異なる。介入を選ぶ前の問題整理に使えるが、三項目を埋めるだけで効果が保証されるわけではない。本人の希望、環境の制約、実際の結果を確かめながら設計する。","old_note":null,"new_note":null},{"id":"kb_1033","title":"EASTフレームワーク","old_summary":"行動を促す設計を、簡単に、魅力的に、社会的に、適切な時に、という四つの観点で点検する実践枠組み。提出を増やしたいなら入力工程を減らし、要点を目立たせ、適切な規範情報を伝え、準備できる時点で案内する。","new_summary":"行動を促す設計を、簡単に、魅力的に、社会的に、適切な時に、という四つの観点で点検する実践枠組み。提出を増やしたいなら入力工程を減らし、要点を目立たせ、適切な規範情報を伝え、準備できる時点で案内する。施策の案出に使い、その後は比較や実験で結果を確かめる。人を必ず動かす四法則ではなく、対象や状況で有効性は変わる。誤った社会情報や、本人の選択を妨げる誘導を正当化しない。","old_note":null,"new_note":null},{"id":"kb_947","title":"学習性勤勉さ","old_summary":"努力を要する課題で報われる経験が、努力への抵抗を弱め、別の課題での粘り強さにもつながるという理論。","new_summary":"努力を要する活動で報われる経験が、努力そのものへの抵抗を弱め、別の課題での粘り強さにもつながりうるという理論。才能や根性だけで継続を説明せず、難しさと成果の結びつきを考える。無理を長く続ければよいという教訓ではなく、報酬の与え方や課題の条件によって転移は異なる。","old_note":null,"new_note":null},{"id":"kb_1034","title":"健康信念モデル","old_summary":"健康に関わる行動を、問題が自分に起こる可能性や重大さ、行動の利益と障壁、きっかけなどの認識から理解するモデル。健診を勧める場合、必要性を理解していないのか、費用や時間が障害なのかを分けて聞く。","new_summary":"健康に関わる行動を、問題が自分に起こる可能性や重大さ、行動の利益と障壁、きっかけなどの認識から理解するモデル。健診を勧める場合、必要性を理解していないのか、費用や時間が障害なのかを分けて聞く。恐ろしさだけを強調せず、実行できる選択肢を確かめる手掛かりになる。後の拡張では自己効力感なども考慮する。信念だけで行動が決まるとは限らず、医療へのアクセスや制度の制約もある。個別の診断や治療判断に代わるものではない。","old_note":null,"new_note":null},{"id":"kb_948","title":"足場かけ","old_summary":"学習者が一人では難しい課題に取り組めるよう支え、習熟に合わせて支援を減らしていく方法。手本やヒントを、本人の理解に応じて調整する。","new_summary":"学習者が一人では難しい課題へ取り組めるよう、必要な部分を支援し、できるようになるにつれて支援を減らす方法。手順の一部を示し、残りを本人が試すような支援が含まれる。教える側がすべてを代行せず、本人の理解に合わせる。最近接発達領域は学べる範囲の概念であり、足場かけという支援方法と同義ではない。","old_note":null,"new_note":null},{"id":"kb_1031","title":"行動形成（シェイピング）","old_summary":"目標行動に少しずつ近づく反応を選んで強化し、まだできない行動を形成する学習手続き。発表練習なら、まず短く声に出すこと、次に要点を伝えることへと、達成基準を段階的に上げる。","new_summary":"目標行動に少しずつ近づく反応を選んで強化し、まだできない行動を形成する学習手続き。発表練習なら、まず短く声に出すこと、次に要点を伝えることへと、達成基準を段階的に上げる。現在の行動、次の小さな基準、強化するタイミングを具体化して使う。作業を分割するだけではシェイピングとは限らず、結果に応じた強化の条件が重要である。急に基準を上げたり、相手が望まない目標へ誘導したりしない。","old_note":null,"new_note":null},{"id":"kb_1035","title":"保護動機理論","old_summary":"脅威への評価と、対処できるかの評価が、防御的な行動の意図にどう関わるかを説明する理論。情報セキュリティの注意喚起では、被害の深刻さだけでなく、推奨行動の有効性や自分に実行できる感覚が重要になる。","new_summary":"脅威への評価と、対処できるかの評価が、防御的な行動の意図にどう関わるかを説明する理論。情報セキュリティの注意喚起では、被害の深刻さだけでなく、推奨行動の有効性や自分に実行できる感覚が重要になる。警告と具体的な対処手順を一緒に設計するために使える。後の拡張ではコストや報酬なども扱う。恐怖を強めるほど良いという理論ではなく、回避や否認が起きる可能性もある。意図と実行、知覚と実際の能力を分けて評価する。","old_note":null,"new_note":null},{"id":"kb_1036","title":"健康行動プロセスアプローチ","old_summary":"健康行動を始めようとする動機形成と、その後の計画、実行、維持、再開を分けて考える枠組み。運動したいと思う段階と、忙しい週にどう続けるかを決める段階では、必要な支援が違う。","new_summary":"健康行動を始めようとする動機形成と、その後の計画、実行、維持、再開を分けて考える枠組み。運動したいと思う段階と、忙しい週にどう続けるかを決める段階では、必要な支援が違う。いつどこで行うかに加え、障害が出た際の対処や中断後の再開も具体化する。各段階で自己効力感の役割を考えるが、誰もが固定した順序を一度だけ進むわけではない。生活上の資源や本人の希望を確認し、モデルを治療手順や成果の保証として使わない。","old_note":null,"new_note":null},{"id":"kb_1037","title":"フィードバック介入理論","old_summary":"成績についての情報が、課題の処理、学び方、自己への注意のどこへ向けられるかによって、その後の成績が変わると考える理論。人格への評価ばかりを伝えると、作業の改善より自分を守ることへ注意が移る場合がある。","new_summary":"成績についての情報が、課題の処理、学び方、自己への注意のどこへ向けられるかによって、その後の成績が変わると考える理論。人格への評価ばかりを伝えると、作業の改善より自分を守ることへ注意が移る場合がある。指導では具体的な課題、目標との差、次に試す行動へ焦点を合わせ、結果を確かめる。フィードバックは必ず成績を高めるわけではない。理論は効果の違いを説明する枠組みで、唯一の正しい伝え方を決めるものではない。","old_note":null,"new_note":null},{"id":"kb_572","title":"目標調整理論","old_summary":"達成が難しくなった目標から離れ、新たな目標へ力を振り向けることで適応を保つという理論。目標へのこだわりと、再出発のしやすさを扱う。","new_summary":"達成不能になった目標への関与を弱め、代替目標へ再関与することで適応を保つ過程を扱う。諦めを単なる失敗ではなく、資源を再配分する自己調整として捉える。","old_note":null,"new_note":null},{"id":"kb_539","title":"プロセス目標","old_summary":"成果につながる行動や手順そのものを目標にすること。「合格する」に対して「毎日問題を解く」のように、今実行できることを明確にする。","new_summary":"最終成果ではなく、成果につながる具体的な行動や手順を目標にすること。結果を直接制御できない状況でも、今日実行できる行動へ注意を戻せる。","old_note":null,"new_note":null},{"id":"kb_1026","title":"意図と行動のギャップ","old_summary":"行うつもりがあることと、実際に実行することの間に隔たりがあること。運動しようと決めても、時間や場所を決めず、仕事後には始められない場合などがある。","new_summary":"行うつもりがあることと、実際に実行することの間に隔たりがあること。運動しようと決めても、時間や場所を決めず、仕事後には始められない場合などがある。意欲を高めるだけでなく、機会、手順、障害、思い出すきっかけまで確かめる必要を示す。実行意図や環境の調整を検討する入口になるが、ギャップ自体は一つの原因を指さない。実行できなかった人を無責任と評価する名称ではなく、資源や機会の制約も含めて考える。","old_note":null,"new_note":null},{"id":"kb_1027","title":"計画的行動理論","old_summary":"行動への態度、周囲が期待していると感じる規範、自分に実行できるという認識が意図を形成し、意図と実際の統制可能性が行動に関わるとする理論。研修への参加を考えるなら、有益と思うか、周囲の期待、時間や手段の確保を分けて尋ねられる。","new_summary":"行動への態度、周囲が期待していると感じる規範、自分に実行できるという認識が意図を形成し、意図と実際の統制可能性が行動に関わるとする理論。研修への参加を考えるなら、有益と思うか、周囲の期待、時間や手段の確保を分けて尋ねられる。計画は立てたのに実行しない理由を整理する枠組みになる。ただし意図だけで行動は決まらず、習慣、感情、制度的制約もある。全行動を精密に予測する式として使わない。","old_note":null,"new_note":null},{"id":"kb_897","title":"選択盲","old_summary":"自分が選んだ結果を別のものにすり替えられても、気づかずにその選択理由を説明してしまうことがある現象。","new_summary":"自分が選んだものと提示された結果がすり替わっていても、その不一致に気づかず、結果を選んだ理由を説明することがある現象。原著は顔写真の魅力による選択課題を使った。選択の理由を後から述べた言葉だけで確定せず、実際に選んだ記録とも照合する必要を示す。すべての好みが不安定だという主張ではなく、気づき方は条件に左右される。","old_note":null,"new_note":null},{"id":"kb_1013","title":"左端数字効果","old_summary":"数値の左端の桁が変わると、実際の差以上に大きな違いとして受け止められることがある現象。例えば1,000円から999円への差を、同じ1円差の別の組合せより大きく感じる場合がある。","new_summary":"数値の左端の桁が変わると、実際の差以上に大きな違いとして受け止められることがある現象。例えば1,000円から999円への差を、同じ1円差の別の組合せより大きく感じる場合がある。価格を比べる際は、左端の印象だけでなく差額や総額を計算して確かめる。すべての端数価格が同じ効果をもつわけではなく、比較対象や注意の向け方で変わる。安さの印象を説明する概念であり、価格だけで品質や購入意向が決まるという法則ではない。","old_note":null,"new_note":null},{"id":"kb_1014","title":"貨幣錯覚","old_summary":"お金の価値を判断する際、物価変動を考慮した実質額より、名目額に引きずられること。物価が給与より大きく上がっても、給与の数字が増えたため生活が豊かになったと感じる場合などがある。","new_summary":"お金の価値を判断する際、物価変動を考慮した実質額より、名目額に引きずられること。物価が給与より大きく上がっても、給与の数字が増えたため生活が豊かになったと感じる場合などがある。報酬や長期の計画を比べるとき、何がどれだけ買えるかという基準を併記する手掛かりになる。名目額を使うこと自体が誤りではなく、契約や制度には名目額が重要な場面もある。所得の変化への反応をすべて貨幣錯覚で説明しない。","old_note":null,"new_note":null},{"id":"kb_1015","title":"指数成長バイアス","old_summary":"一定割合で増える過程を、一定量ずつ増えるように捉え、将来の増加を過小評価する傾向。毎年同じ割合で増える量は元本や基数も変わるため、最初の増加額をそのまま年数倍した予想とは違ってくる。","new_summary":"一定割合で増える過程を、一定量ずつ増えるように捉え、将来の増加を過小評価する傾向。毎年同じ割合で増える量は元本や基数も変わるため、最初の増加額をそのまま年数倍した予想とは違ってくる。長期の費用や累積量を考える際は、直感だけでなく表や式で複数時点を確かめる。実際の成長がいつまでも同じ割合で続くという意味ではなく、上限や条件変化も別に検討する。計算の誤りと、予測モデル自体の誤りを分ける。","old_note":null,"new_note":null},{"id":"kb_1016","title":"顕著性バイアス","old_summary":"目立つ情報へ注意や重みが偏り、目立ちにくいが重要な情報が十分に考慮されない傾向。印象的な一件の苦情ばかりが会議で語られ、全体の発生率や利用者数が見落とされる場合などがある。","new_summary":"目立つ情報へ注意や重みが偏り、目立ちにくいが重要な情報が十分に考慮されない傾向。印象的な一件の苦情ばかりが会議で語られ、全体の発生率や利用者数が見落とされる場合などがある。判断では、目立つ理由と重要である理由を分け、共通の指標で候補を並べる。何が目立つかは比較状況や目的でも変わる。利用可能性ヒューリスティックと関わるが、思い出しやすさだけでなく、現在の比較で突出した属性に重みが付く点も扱う。","old_note":null,"new_note":null},{"id":"kb_1017","title":"選好逆転","old_summary":"同じ選択肢でも、選ぶ、値段を付けるなどの評価方法によって好みの順位が逆になる現象。二つのくじのうち当たりやすい方を選ぶのに、売却価格は大きな賞金の方へ高く付ける場合などが例になる。","new_summary":"同じ選択肢でも、選ぶ、値段を付けるなどの評価方法によって好みの順位が逆になる現象。二つのくじのうち当たりやすい方を選ぶのに、売却価格は大きな賞金の方へ高く付ける場合などが例になる。選択の理由を確認するときは、質問形式や測り方が判断を変えていないかを点検する。新しい情報や価値観の変化による当然の好みの変化とは区別する。誰にも本当の好みがないという結論ではなく、引き出し方による不整合を扱う。","old_note":null,"new_note":null},{"id":"kb_1018","title":"リスク感情理論","old_summary":"危険について考えた確率や結果の評価と、その瞬間に生じる恐怖や不安が食い違い、感情が行動を左右しうるという仮説。統計では低リスクと理解していても、鮮明な事故映像を見た直後は避けたくなる場合などがある。","new_summary":"危険について考えた確率や結果の評価と、その瞬間に生じる恐怖や不安が食い違い、感情が行動を左右しうるという仮説。統計では低リスクと理解していても、鮮明な事故映像を見た直後は避けたくなる場合などがある。判断では計算した評価と現在の感情を別々に言葉にし、両方の情報を確かめる。感情を無視すべきという意味ではない。一般的な感情ヒューリスティックより、リスクに直面した感情と認知的評価の乖離に焦点を当てる。","old_note":null,"new_note":null},{"id":"kb_1019","title":"参照価格効果","old_summary":"提示価格を、過去の購入価格や通常価格などの比較基準に照らして評価すること。以前は高かったという表示を見ると、今の価格を割安に感じる場合などがある。","new_summary":"提示価格を、過去の購入価格や通常価格などの比較基準に照らして評価すること。以前は高かったという表示を見ると、今の価格を割安に感じる場合などがある。買い物や見積もりの比較では、比較基準が実際の取引や必要に合っているかを確かめる。アンカリングと関連するが、価格の記憶や市場で形成した基準を含む。人によって参照価格は異なり、常に同じ値が保たれるわけではない。値引き率だけでなく支払総額と代替案を確認する。","old_note":null,"new_note":null},{"id":"kb_1020","title":"分割価格効果","old_summary":"価格を本体代と手数料などに分けて示すことで、総額の認識や購入判断が変わること。安い本体価格に送料を別記すると、総額では高くても安い印象が残る場合がある。","new_summary":"価格を本体代と手数料などに分けて示すことで、総額の認識や購入判断が変わること。安い本体価格に送料を別記すると、総額では高くても安い印象が残る場合がある。比較するときは、必要な追加費用を含む総額を同じ条件で並べる。分割表示が常に需要を増やすとは限らず、手数料の納得感や明示の仕方でも反応は変わる。支払いを複数回に分ける分割払いとは異なり、情報の示し方と処理の問題として捉える。","old_note":null,"new_note":null},{"id":"kb_1021","title":"スノッブ効果","old_summary":"他の人が多く持つことにより、その品の魅力や需要が下がること。珍しい品を選んだ人が、広く普及すると別の品へ移る場合などが例になる。","new_summary":"他の人が多く持つことにより、その品の魅力や需要が下がること。珍しい品を選んだ人が、広く普及すると別の品へ移る場合などが例になる。他者との差別化が価値に含まれる選択を理解する手掛かりになる。希少な物を好む理由がすべてスノッブ効果とは限らず、実際の品質や利用価値も区別する。価格が高いこと自体を地位の表示として求めるヴェブレン効果や、流行に合わせるバンドワゴン効果とは説明する方向が異なる。","old_note":null,"new_note":null},{"id":"kb_1022","title":"ヴェブレン効果","old_summary":"高い価格が地位や富の表示として価値をもち、価格の高さが需要を支えること。品質が同じでも、高価だと周囲に伝わる品が選ばれる場合などを考える。","new_summary":"高い価格が地位や富の表示として価値をもち、価格の高さが需要を支えること。品質が同じでも、高価だと周囲に伝わる品が選ばれる場合などを考える。消費の理由を振り返る際、実際の使い勝手と地位の表示としての価値を分けてみられる。高価な品を買う行動がすべてこの効果ではなく、品質や希少性への評価とも区別する。値上げすれば必ず売れるという法則ではない。他者が持たないことを好むスノッブ効果とも異なる。","old_note":null,"new_note":null},{"id":"kb_1023","title":"ディスポジション効果","old_summary":"利益が出た資産は早く売り、損失が出た資産は長く持ち続ける傾向。利益を確定する安心と、損失を認める抵抗が、現在の見込みとは別に判断へ入り込む場合がある。","new_summary":"利益が出た資産は早く売り、損失が出た資産は長く持ち続ける傾向。利益を確定する安心と、損失を認める抵抗が、現在の見込みとは別に判断へ入り込む場合がある。過去の取得価格への感情と、今後の判断根拠を分けて振り返る概念として使える。ただし税、手数料、資金需要、合理的な見通しによる売買もあり、個別の保有を直ちに誤りとは決められない。損失回避を資産の処分行動に適用した現象で、売買の推奨ルールではない。","old_note":null,"new_note":null},{"id":"kb_1024","title":"近視眼的損失回避","old_summary":"損失を強く嫌う傾向と、結果を短い間隔で評価することが組み合わさり、長期とは異なるリスク判断になるという説明。変動する成果を毎日確かめると、小さな下落を何度も経験して慎重になりやすい場合などを考える。","new_summary":"損失を強く嫌う傾向と、結果を短い間隔で評価することが組み合わさり、長期とは異なるリスク判断になるという説明。変動する成果を毎日確かめると、小さな下落を何度も経験して慎重になりやすい場合などを考える。評価頻度が自分の反応にどう影響するかを振り返る手掛かりになる。長く見ればどんなリスクも安全になるという意味ではなく、必要な監視を減らす指示でもない。現在の利益を優先する現在バイアスとは機序が異なる。","old_note":null,"new_note":null},{"id":"kb_1025","title":"確率マッチング","old_summary":"起こる結果の頻度に合わせて、予測や選択の割合を配分する傾向。独立に赤が7割出る課題で、赤を7割、青を3割予測するような例である。","new_summary":"起こる結果の頻度に合わせて、予測や選択の割合を配分する傾向。独立に赤が7割出る課題で、赤を7割、青を3割予測するような例である。正答数だけを最大化するなら毎回赤を選ぶ方が有利な設定でも、割合を合わせる行動が見られる。確率的な選択を点検する際、目的が予測の的中、探索、分配のどれかを明確にする。環境が変わる場合や探索に価値がある場合を含め、すべての確率的選択を非合理とはしない。","old_note":null,"new_note":null},{"id":"kb_1038","title":"投影バイアス","old_summary":"現在の好みや身体状態が将来も続くと見積もり、将来の自分の選好の変化を十分に考慮できない傾向。空腹時に翌週の食料を買うと、後で必要な量より多く選ぶ場合などがある。","new_summary":"現在の好みや身体状態が将来も続くと見積もり、将来の自分の選好の変化を十分に考慮できない傾向。空腹時に翌週の食料を買うと、後で必要な量より多く選ぶ場合などがある。先の予定や購入を決めるときは、今とは異なる状態でどう感じるかを具体的に想像し、過去の記録も確かめる。単に現在の利益を優先する現在バイアスとは違い、将来の好みの予測が対象になる。将来は今と必ず違うと決めつけるのではなく、変化の可能性を見積もる。","old_note":null,"new_note":null},{"id":"kb_1039","title":"認識ヒューリスティック","old_summary":"二つの対象の一方だけを知っている場合、その知っている方がある基準で大きいと推測する簡便な方略。二都市の人口を比べる際、名前を聞いたことのある都市を選ぶような例である。","new_summary":"二つの対象の一方だけを知っている場合、その知っている方がある基準で大きいと推測する簡便な方略。二都市の人口を比べる際、名前を聞いたことのある都市を選ぶような例である。知っているかどうかが対象の基準と相関する環境では有効な場合がある。聞き覚えを根拠にした判断では、その相関が今の環境にあるかを確かめる。広告で知られた品など、知名度が品質と結び付かない場面では外れうる。再認主導意思決定モデルとは異なる。","old_note":null,"new_note":null},{"id":"kb_1040","title":"Take-the-bestヒューリスティック","old_summary":"予測力の高い手掛かりから順に二候補を比べ、最初に差がついた手掛かりだけで判断を止める方略。どちらの都市が大きいかを考えるとき、重要と見積もる特徴から調べ、区別できた段階で選ぶ。","new_summary":"予測力の高い手掛かりから順に二候補を比べ、最初に差がついた手掛かりだけで判断を止める方略。どちらの都市が大きいかを考えるとき、重要と見積もる特徴から調べ、区別できた段階で選ぶ。すべての情報を合計せずとも、不確実な環境では良い予測になる場合がある。手掛かりの順序や環境構造に依存するため、重要な条件を無視してよいという勧めではない。必須条件の確認や、安全に関わる判断には別の点検が必要になる。","old_note":null,"new_note":null},{"id":"kb_1041","title":"側面ごとの消去法","old_summary":"選択肢を比べる側面を重要さに応じて選び、その条件を満たさない候補を順に除く意思決定モデル。原モデルでは、比較する側面を確率的に選ぶ。","new_summary":"選択肢のある側面に着目し、その側面を満たさない候補を除く過程を繰り返す選択モデル。住まいを選ぶ際、通勤時間、費用、設備などで候補を順次絞る場合が身近な例になる。原モデルでは側面が重みに応じて確率的に選ばれる点を含む。実務では除外条件を明示する手掛かりになるが、条件の順序で残る候補が変わる可能性を確かめる。全属性の得点を足す方法や、最初の差で二候補を選ぶTake-the-bestとは異なる。","old_note":null,"new_note":null},{"id":"kb_1042","title":"スラッジ","old_summary":"必要な行動を妨げる過大な手間、分かりにくさ、待ち時間などの摩擦を点検する概念。申請に何度も同じ情報を入力させる、解約方法が見つからないといった状況で、形式上の選択肢があっても利用しにくくなる。","new_summary":"必要な行動を妨げる過大な手間、分かりにくさ、待ち時間などの摩擦を点検する概念。申請に何度も同じ情報を入力させる、解約方法が見つからないといった状況で、形式上の選択肢があっても利用しにくくなる。改善では工程や負担を可視化し、目的に比べ不要な障壁を減らす。本人を助ける確認手順まで無条件に取り除く意味ではない。ナッジの単なる反対語ではなく、利益、必要性、分配の不公平も検討して摩擦を評価する。","old_note":null,"new_note":null},{"id":"kb_1043","title":"不平等回避","old_summary":"自分と他者の取り分の不平等が、不利益でも有利でも効用に影響すると捉える社会的選好のモデル。自分の取り分が増えても極端に不公平な分配を拒んだり、自分の利益を減らして差を縮めたりする行動を考える。","new_summary":"自分と他者の取り分の不平等が、不利益でも有利でも効用に影響すると捉える社会的選好のモデル。自分の取り分が増えても極端に不公平な分配を拒んだり、自分の利益を減らして差を縮めたりする行動を考える。交渉や分配では総額だけでなく、誰とどう比べられているかを確かめる視点になる。人は全員同じ平等を求めるわけではなく、貢献、手続き、関係によっても反応は変わる。すべての協力や公正判断を説明する唯一の理論ではない。","old_note":null,"new_note":null},{"id":"kb_1044","title":"生態学的合理性","old_summary":"判断方略の良し悪しを、形式的に複雑かどうかだけでなく、用いる環境の情報構造との適合で評価する立場。少数の確かな手掛かりで判断する方法が、データが少ない場面では複雑な計算よりよい予測になる場合がある。","new_summary":"判断方略の良し悪しを、形式的に複雑かどうかだけでなく、用いる環境の情報構造との適合で評価する立場。少数の確かな手掛かりで判断する方法が、データが少ない場面では複雑な計算よりよい予測になる場合がある。方略を選ぶ際、利用できる情報、ノイズ、時間、目的を確かめる。単純な直感はいつでも優れるという主張ではなく、どの条件でどの方略が役立つかを検証する。環境保護の行動を合理的と呼ぶ意味とは異なる。","old_note":null,"new_note":null},{"id":"theory-8989915e-3d28-4fad-9521-1bdece206b3f","title":"「墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。」","old_summary":"「墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。」\n— 魯迅\n無花の薔薇 その二（華蓋集続編）\n\n権力が言葉で取り繕っても、虐殺という事実と犠牲は消せないという告発。三・一八事件後の魯迅の怒りを表す一節。","new_summary":"「墨で書いた嘘は、血で書かれた事実を決して覆い隠せない。」\n— 魯迅\n無花の薔薇 その二（華蓋集続編）\n\n三・一八事件の虐殺と、それを覆い隠す政府の言葉を批判した一節。単なる言い訳批判へ縮めず、事実と権力の言葉の緊張を読む。","old_note":"権力が言葉で取り繕っても、虐殺という事実と犠牲は消せないという告発。三・一八事件後の魯迅の怒りを表す一節。","new_note":"三・一八事件の虐殺と、それを覆い隠す政府の言葉を批判した一節。単なる言い訳批判へ縮めず、事実と権力の言葉の緊張を読む。"},{"id":"kb_334","title":"禍福は糾える縄の如し","old_summary":"幸福と災いは、より合わせた縄のように交互に絡み合うということわざ。今の出来事の意味も、その後の展開によって変わっていく。","new_summary":"災いと幸福は縄のように絡み合い、どちらか一方だけが続くわけではないという教え。","old_note":null,"new_note":null},{"id":"theory-4a83dca9-828a-4f93-8c7c-f945b36de56a","title":"「自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。」","old_summary":"「自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。」\n— 芥川龍之介\n侏儒の言葉\n\n自由には、自分で選び、その結果を引き受ける重さがあるという逆説。澄んでいても息苦しい山頂の空気に、その厳しさを重ねる。","new_summary":"「自由は山頂の空気に似ている。どちらも弱い者には堪えることはできない。」\n— 芥川龍之介\n侏儒の言葉\n\n自由を高所の空気にたとえ、その負担を突きつける逆説。個人の強弱を判定する理論ではなく、自由と責任を問う文学的表現。","old_note":"自由には、自分で選び、その結果を引き受ける重さがあるという逆説。澄んでいても息苦しい山頂の空気に、その厳しさを重ねる。","new_note":"自由を高所の空気にたとえ、その負担を突きつける逆説。個人の強弱を判定する理論ではなく、自由と責任を問う文学的表現。"},{"id":"theory-b16cc75c-68d0-4873-b989-2ed788bd404b","title":"「人気者になるには、凡庸でなければならない。」","old_summary":"「人気者になるには、凡庸でなければならない。」\n— オスカー・ワイルド\nドリアン・グレイの肖像\n\n誰からも好かれようとすれば、際立った個性や鋭さは歓迎されにくいという皮肉。『ドリアン・グレイの肖像』のヘンリー卿の台詞。","new_summary":"「人気者になるには、凡庸でなければならない。」\n— オスカー・ワイルド\nドリアン・グレイの肖像\n\n周囲へ強い印象を与えることと、誰からも好かれることの矛盾を皮肉る台詞。作者本人の成功法則や、大衆心理の実証結果ではない。","old_note":"誰からも好かれようとすれば、際立った個性や鋭さは歓迎されにくいという皮肉。『ドリアン・グレイの肖像』のヘンリー卿の台詞。","new_note":"周囲へ強い印象を与えることと、誰からも好かれることの矛盾を皮肉る台詞。作者本人の成功法則や、大衆心理の実証結果ではない。"},{"id":"theory-c83321fd-d076-4d5c-b270-6af925c204a5","title":"「人は、自分が幸福だと知らないから不幸なのだ。ただそれだけのために。」","old_summary":"「人は、自分が幸福だと知らないから不幸なのだ。ただそれだけのために。」\n— ドストエフスキー\n悪霊\n\nすでにある幸福に気づけないことが、不幸の感覚を生むという逆説。『悪霊』のキリーロフは、幸福を自覚することに救いを見いだす。","new_summary":"「人は、自分が幸福だと知らないから不幸なのだ。ただそれだけのために。」\n— ドストエフスキー\n悪霊\n\nキリーロフが幸福をどう自覚するかを語る台詞。困難や病気を本人の考え方だけの責任にする根拠ではない。","old_note":"すでにある幸福に気づけないことが、不幸の感覚を生むという逆説。『悪霊』のキリーロフは、幸福を自覚することに救いを見いだす。","new_note":"キリーロフが幸福をどう自覚するかを語る台詞。困難や病気を本人の考え方だけの責任にする根拠ではない。"},{"id":"theory-5f7a3841-2826-4bf5-8da4-d7265b80de9b","title":"「人生は一箱のマッチに似ている。重大に扱うのは莫迦莫迦しい。重大に扱わなければ危険である。」","old_summary":"「人生は一箱のマッチに似ている。重大に扱うのは莫迦莫迦しい。重大に扱わなければ危険である。」\n— 芥川龍之介\n侏儒の言葉\n\n人生は、重く考えすぎても滑稽で、軽く扱いすぎても危うい。その両義性を、手軽でありながら火を生むマッチに重ねた言葉。","new_summary":"「人生は一箱のマッチに似ている。重大に扱うのは莫迦莫迦しい。重大に扱わなければ危険である。」\n— 芥川龍之介\n侏儒の言葉\n\n人生を重く扱いすぎる滑稽さと、軽く扱う危険を一つの比喩で並べる。どちらか一方へ割り切れない判断の両義性を示す。","old_note":"人生は、重く考えすぎても滑稽で、軽く扱いすぎても危うい。その両義性を、手軽でありながら火を生むマッチに重ねた言葉。","new_note":"人生を重く扱いすぎる滑稽さと、軽く扱う危険を一つの比喩で並べる。どちらか一方へ割り切れない判断の両義性を示す。"},{"id":"theory-62543145-f91d-448d-aece-2a44802164f8","title":"「人間の罪のなかで、私が何より憎むのは不機嫌だ。」","old_summary":"「人間の罪のなかで、私が何より憎むのは不機嫌だ。」\n— ゲーテ\n若きウェルテルの悩み\n\n自分の不機嫌が周囲の楽しみや心の安らぎまで損なうことへの、強い嫌悪を表す言葉。ウェルテルが、人と共にいるときの機嫌を問う。","new_summary":"「人間の罪のなかで、私が何より憎むのは不機嫌だ。」\n— ゲーテ\n若きウェルテルの悩み\n\n候補の「最大の罪」は、原文では語り手が最も憎む罪という主観的表現。周囲へ及ぶ機嫌の影響を読む台詞で、作者による道徳の順位表ではない。","old_note":"自分の不機嫌が周囲の楽しみや心の安らぎまで損なうことへの、強い嫌悪を表す言葉。ウェルテルが、人と共にいるときの機嫌を問う。","new_note":"候補の「最大の罪」は、原文では語り手が最も憎む罪という主観的表現。周囲へ及ぶ機嫌の影響を読む台詞で、作者による道徳の順位表ではない。"},{"id":"theory-a16caa2e-318b-4527-bd2a-0dfb9b6a1f33","title":"「涙でパンを食べたことも、悲しみの夜を寝台で泣いて過ごしたこともない者は、天上の力であるあなたがたを知らない。」","old_summary":"「涙でパンを食べたことも、悲しみの夜を寝台で泣いて過ごしたこともない者は、天上の力であるあなたがたを知らない。」\n— ゲーテ\nヴィルヘルム・マイスターの修業時代\n\n深い苦しみを経験した者にこそ見えてくる、人生を動かす力があるという詩句。涙の食事と眠れぬ夜が、竪琴弾きの悲痛を伝える。","new_summary":"「涙でパンを食べたことも、悲しみの夜を寝台で泣いて過ごしたこともない者は、天上の力であるあなたがたを知らない。」\n— ゲーテ\nヴィルヘルム・マイスターの修業時代\n\n「人生の味」という流通する要約を、苦痛と天上の力を歌う原詩へ戻した。苦難を他者へ強いる教訓や、苦しみを幸福の必要条件とする主張ではない。","old_note":"深い苦しみを経験した者にこそ見えてくる、人生を動かす力があるという詩句。涙の食事と眠れぬ夜が、竪琴弾きの悲痛を伝える。","new_note":"「人生の味」という流通する要約を、苦痛と天上の力を歌う原詩へ戻した。苦難を他者へ強いる教訓や、苦しみを幸福の必要条件とする主張ではない。"},{"id":"theory-e634c0c0-8300-44e5-a28f-916300973eb1","title":"「いちばんだましやすい相手は、自分自身だ。」","old_summary":"「いちばんだましやすい相手は、自分自身だ。」\n— ブルワー＝リットン\nThe Disowned（勘当された者）\n\n自分の望みに都合のよい説明ほど、自分自身は信じやすいという警句。自分の動機や善良さへの確信にも、盲点がある。","new_summary":"「いちばんだましやすい相手は、自分自身だ。」\n— ブルワー＝リットン\nThe Disowned（勘当された者）\n\n自分の動機や善良さへの確信も、自己欺瞞から自由ではないと刺す台詞。話者の応答と、相手がそれをどう受け取るかの落差も含めて読む。","old_note":"自分の望みに都合のよい説明ほど、自分自身は信じやすいという警句。自分の動機や善良さへの確信にも、盲点がある。","new_note":"自分の動機や善良さへの確信も、自己欺瞞から自由ではないと刺す台詞。話者の応答と、相手がそれをどう受け取るかの落差も含めて読む。"},{"id":"theory-e1df3caa-9877-4eed-a549-162cc3bdaca0","title":"「恋愛はただ性欲の詩的表現を受けたものである。」","old_summary":"「恋愛はただ性欲の詩的表現を受けたものである。」\n— 芥川龍之介\n侏儒の言葉\n\n欲望が想像と言葉によって美しく表現されるところに、恋愛らしさが生まれるという見方。恋の理想化を、皮肉を込めて捉える。","new_summary":"「恋愛はただ性欲の詩的表現を受けたものである。」\n— 芥川龍之介\n侏儒の言葉\n\n欲望が言葉や想像によって恋愛へ姿を変えるという、皮肉を含む見方。続く原文は、詩的表現を受けない性欲は恋愛と呼ぶに値しないと述べる。","old_note":"欲望が想像と言葉によって美しく表現されるところに、恋愛らしさが生まれるという見方。恋の理想化を、皮肉を込めて捉える。","new_note":"欲望が言葉や想像によって恋愛へ姿を変えるという、皮肉を含む見方。続く原文は、詩的表現を受けない性欲は恋愛と呼ぶに値しないと述べる。"},{"id":"theory-acb4311e-b6ca-416c-8d06-06cff53444b2","title":"「恋は飢えによって生き、食べ物を与えられて死ぬ。」","old_summary":"「恋は飢えによって生き、食べ物を与えられて死ぬ。」\n— アルフレッド・ド・ミュッセ\nマルドッシュ（初期詩集）\n\n恋は満たされない思いによって燃え続け、十分に満たされると勢いを失うという逆説。欲望の持続と充足の緊張を、飢えと食事にたとえる。","new_summary":"「恋は飢えによって生き、食べ物を与えられて死ぬ。」\n— アルフレッド・ド・ミュッセ\nマルドッシュ（初期詩集）\n\n恋が満たされないことで続き、充足によって衰えるという逆説を詠む。恋愛相手を意図的に不安にさせる手法や、関係の普遍法則としては扱わない。","old_note":"恋は満たされない思いによって燃え続け、十分に満たされると勢いを失うという逆説。欲望の持続と充足の緊張を、飢えと食事にたとえる。","new_note":"恋が満たされないことで続き、充足によって衰えるという逆説を詠む。恋愛相手を意図的に不安にさせる手法や、関係の普遍法則としては扱わない。"},{"id":"theory-ba3eb39f-7dd4-4795-8eb0-c17c2b34fd1e","title":"「青春は、何もかも実験である。」","old_summary":"「青春は、何もかも実験である。」\n— R・L・スティーヴンソン\n芸術の道を志す若い紳士への手紙\n\n若い時期は、試して初めて自分の好みや可能性が分かるという言葉。未完成であることを、新しい経験から自分を知る余地として捉える。","new_summary":"「青春は、何もかも実験である。」\n— R・L・スティーヴンソン\n芸術の道を志す若い紳士への手紙\n\n若い時期を、まだ知らない自分と世界を繰り返し出会わせる実験として描く。失敗を無条件に美化する言葉ではなく、自己理解が試行の中で育つという見方。","old_note":"若い時期は、試して初めて自分の好みや可能性が分かるという言葉。未完成であることを、新しい経験から自分を知る余地として捉える。","new_note":"若い時期を、まだ知らない自分と世界を繰り返し出会わせる実験として描く。失敗を無条件に美化する言葉ではなく、自己理解が試行の中で育つという見方。"},{"id":"theory-d15357a9-73da-4286-859e-91a7ebcb5f85","title":"「コロンブスが幸福だったのは、アメリカを発見したときではなく、発見しつつあったときだ。」","old_summary":"「コロンブスが幸福だったのは、アメリカを発見したときではなく、発見しつつあったときだ。」\n— ドストエフスキー\n白痴\n\n幸福は到達した瞬間だけでなく、発見へ向かって心を動かされている過程にも宿るという見方。『白痴』のイッポリートの独白の一節。","new_summary":"「コロンブスが幸福だったのは、アメリカを発見したときではなく、発見しつつあったときだ。」\n— ドストエフスキー\n白痴\n\n人生を発見し続ける過程へ目を向ける、作中人物の切迫した独白。コロンブスの実際の心理を史実として記録した文でも、達成後は必ず不幸になるという研究でもない。","old_note":"幸福は到達した瞬間だけでなく、発見へ向かって心を動かされている過程にも宿るという見方。『白痴』のイッポリートの独白の一節。","new_note":"人生を発見し続ける過程へ目を向ける、作中人物の切迫した独白。コロンブスの実際の心理を史実として記録した文でも、達成後は必ず不幸になるという研究でもない。"},{"id":"theory-a70e3a53-86c5-45e0-afb4-97e081936b53","title":"「借り手にも貸し手にもなるな。貸せば、金も友も失いがちだから。」","old_summary":"「借り手にも貸し手にもなるな。貸せば、金も友も失いがちだから。」\n— シェイクスピア\nハムレット\n\n金銭の貸し借りは、金の損失と友情の破綻を同時に招きかねないという戒め。『ハムレット』で、ポローニアスが旅立つ息子に語る。","new_summary":"「借り手にも貸し手にもなるな。貸せば、金も友も失いがちだから。」\n— シェイクスピア\nハムレット\n\n貸した金だけでなく友情まで失う二重の損失を、父が子へ戒める台詞。作者の金融理論や、あらゆる借入れを禁じる普遍規則ではない。","old_note":"金銭の貸し借りは、金の損失と友情の破綻を同時に招きかねないという戒め。『ハムレット』で、ポローニアスが旅立つ息子に語る。","new_note":"貸した金だけでなく友情まで失う二重の損失を、父が子へ戒める台詞。作者の金融理論や、あらゆる借入れを禁じる普遍規則ではない。"},{"id":"kb_595","title":"「観察の場では、偶然は準備のできた心だけに味方する。」","old_summary":"「観察の場では、偶然は準備のできた心だけに味方する。」\n— パスツール\nドゥエーでの演説\n\n偶然の出来事を発見に変えるのは、それを見抜けるだけの知識と問題意識だという言葉。準備が、思いがけない機会の意味に気づかせる。","new_summary":"「観察の場では、偶然は準備のできた心だけに味方する。」\n— パスツール\nドゥエーでの演説\n\n偶然の発見を、知識や問題意識を持つ人が見抜くという言葉。準備が幸運そのものを生むと証明する法則ではない。","old_note":"偶然の出来事を発見に変えるのは、それを見抜けるだけの知識と問題意識だという言葉。準備が、思いがけない機会の意味に気づかせる。","new_note":"偶然の発見を、知識や問題意識を持つ人が見抜くという言葉。準備が幸運そのものを生むと証明する法則ではない。"},{"id":"theory-386c4608-d46d-4782-b912-36c85aa8024d","title":"「時間は友情を強くし、恋を弱くする。」","old_summary":"「時間は友情を強くし、恋を弱くする。」\n— ラ・ブリュイエール\nカラクテール\n\n長い付き合いが友情の信頼を育てる一方、恋の新鮮な熱は時とともに薄れるという対比。二つの親密さで、時間の働き方の違いを捉える。","new_summary":"「時間は友情を強くし、恋を弱くする。」\n— ラ・ブリュイエール\nカラクテール\n\n急に生まれる恋と、長い交わりで育つ友情を対照する警句。すべての恋愛や友情が同じ時間経過をたどるという法則ではない。","old_note":"長い付き合いが友情の信頼を育てる一方、恋の新鮮な熱は時とともに薄れるという対比。二つの親密さで、時間の働き方の違いを捉える。","new_note":"急に生まれる恋と、長い交わりで育つ友情を対照する警句。すべての恋愛や友情が同じ時間経過をたどるという法則ではない。"},{"id":"theory-22667bdf-940f-4226-b7ea-28a72128af6b","title":"「友人の片目が不自由なら、私はその人を横顔から見る。」","old_summary":"「友人の片目が不自由なら、私はその人を横顔から見る。」\n— ジョゼフ・ジュベール\nパンセ・エセー・マクシム\n\n友人の欠点ばかりを見つめず、見る角度を変えてその人を受け入れるという寛容の比喩。相手をどう見るかにも、友情は表れる。","new_summary":"「友人の片目が不自由なら、私はその人を横顔から見る。」\n— ジョゼフ・ジュベール\nパンセ・エセー・マクシム\n\n相手の欠点を暴くのでなく、見る角度を変える寛容を比喩で表す。現実の害や不正まで見ないふりをする義務を説いたものとは区別する。","old_note":"友人の欠点ばかりを見つめず、見る角度を変えてその人を受け入れるという寛容の比喩。相手をどう見るかにも、友情は表れる。","new_note":"相手の欠点を暴くのでなく、見る角度を変える寛容を比喩で表す。現実の害や不正まで見ないふりをする義務を説いたものとは区別する。"},{"id":"kb_702","title":"暮らしにくさの中で、視点を探す","old_summary":"人の世の暮らしにくさに対し、見方や距離を変えることで息のつける場所を探すという視点。夏目漱石『草枕』の冒頭をもとにした作品解釈。","new_summary":"夏目漱石『草枕』の社会への息苦しさを踏まえ、暮らしにくさにただ耐えるのではなく、捉え方や距離の取り方を探す視点として示す。","old_note":null,"new_note":null},{"id":"kb_949","title":"ダモクレスの剣","old_summary":"栄光ある地位には、失う恐れや重い責任も伴うことを示す寓話。豪華な宴を楽しむダモクレスの頭上に、一本の毛で吊った剣が置かれる。","new_summary":"栄華を味わうダモクレスの頭上に、細い毛で吊られた剣が置かれるという古典の寓話。外からは恵まれて見える地位にも、常に危険や恐れが伴いうることを示す。成功を羨むときは、その人の責任や失うものも考える。実験で確認された心理効果ではなく、権力と幸福を考えるための比喩として読む。","old_note":null,"new_note":null},{"id":"theory-4e128612-e3f0-4eb9-9c09-e3503466521d","title":"「真の友情では、友を自分へ引き寄せる以上に、自分を友に与える。」","old_summary":"「真の友情では、友を自分へ引き寄せる以上に、自分を友に与える。」\n— モンテーニュ\nエセー\n\n友情とは、相手を自分の都合に合わせるより、自分から心を開き、相手のために差し出す関係だという見方。","new_summary":"「真の友情では、友を自分へ引き寄せる以上に、自分を友に与える。」\n— モンテーニュ\nエセー\n\n友情を、相手を自分に従わせる関係とは反対のものとして語る。無制限な自己犠牲や、相手の要求をすべて引き受けることとは分けて読む。","old_note":"友情とは、相手を自分の都合に合わせるより、自分から心を開き、相手のために差し出す関係だという見方。","new_note":"友情を、相手を自分に従わせる関係とは反対のものとして語る。無制限な自己犠牲や、相手の要求をすべて引き受けることとは分けて読む。"},{"id":"theory-8cd3b27e-6948-4ad0-b961-46eb047b1b67","title":"「友人を疑うことは、友人にだまされることより恥ずかしい。」","old_summary":"「友人を疑うことは、友人にだまされることより恥ずかしい。」\n— ラ・ロシュフコー\n箴言集\n\n裏切られる損失以上に、疑いによって友情を損なうことを重く見る箴言。信じる姿勢そのものに、友情の価値を置く。","new_summary":"「友人を疑うことは、友人にだまされることより恥ずかしい。」\n— ラ・ロシュフコー\n箴言集\n\n裏切られる損より、疑いによって友情を損なう恥を強く置いた箴言。相手の危険な言動を無視する指示や、無条件の信用を証明する理論ではない。","old_note":"裏切られる損失以上に、疑いによって友情を損なうことを重く見る箴言。信じる姿勢そのものに、友情の価値を置く。","new_note":"裏切られる損より、疑いによって友情を損なう恥を強く置いた箴言。相手の危険な言動を無視する指示や、無条件の信用を証明する理論ではない。"},{"id":"kb_326","title":"為せば成る、為さねば成らぬ何事も","old_summary":"物事を実現するには、まず自分が着手しなければ始まらないという教え。行動を起こす責任を自分へ引き戻す言葉。","new_summary":"結果を生む第一条件は、能力の有無を考え続けることではなく、実際に着手することだという教え。","old_note":null,"new_note":null},{"id":"kb_951","title":"テセウスの船","old_summary":"部品をすべて交換した船を、元と同じ船と呼べるかを問う思考実験。材料・形・役割・歴史のうち、何が同一性を支えるのかを考える。","new_summary":"船の部材を順に交換し、すべてが新しくなっても同じ船と言えるかを問う同一性の問題。材料、形、機能、歴史の連続性など、何を同じとみなすかで答えは変わる。組織や自分が変化したとき、何を受け継ぎたいかを考える入口になる。特定の答えが実験で証明された問題ではなく、基準を明らかにする思考実験である。","old_note":null,"new_note":null},{"id":"theory-8bc430c4-f80e-4e74-bb04-aca4a0d9c8bf","title":"「友情のいちばん難しい仕事は、自分の欠点を見せることではなく、友人にその人自身の欠点を気づかせることだ。」","old_summary":"「友情のいちばん難しい仕事は、自分の欠点を見せることではなく、友人にその人自身の欠点を気づかせることだ。」\n— ラ・ロシュフコー\n箴言集\n\n友人の欠点を本人に伝え、気づいてもらうことは難しいという言葉。相手への配慮と、耳の痛いことを伝える率直さが同時に問われる。","new_summary":"「友情のいちばん難しい仕事は、自分の欠点を見せることではなく、友人にその人自身の欠点を気づかせることだ。」\n— ラ・ロシュフコー\n箴言集\n\n自己開示よりも、相手が受け入れにくい指摘を伝える難しさを突く。相手を裁く口実ではなく、友情の配慮と率直さの緊張を読む。","old_note":"友人の欠点を本人に伝え、気づいてもらうことは難しいという言葉。相手への配慮と、耳の痛いことを伝える率直さが同時に問われる。","new_note":"自己開示よりも、相手が受け入れにくい指摘を伝える難しさを突く。相手を裁く口実ではなく、友情の配慮と率直さの緊張を読む。"},{"id":"kb_952","title":"ソクラテス式問答法","old_summary":"問いと答えを重ねて、言葉の定義や判断の前提、考えの矛盾を明らかにする対話の方法。具体例と反例から理解を深める。","new_summary":"答えを一方的に教えるのでなく、問いを重ねて定義や前提、考え同士の整合性を検討する対話の方法。例えば「良い判断とは何か」を具体例と反例で確かめる。分かったつもりの言葉をほどく助けになるが、相手を追い詰める詰問とは区別する。現代の教育や臨床への応用は、古代の対話と同一ではない。","old_note":null,"new_note":null},{"id":"kb_953","title":"アリストテレスの中庸","old_summary":"徳とは、過剰と不足を避け、状況にふさわしいあり方を選ぶことだという考え。例えば勇気は、無謀と臆病の間で適切に行動することにある。","new_summary":"徳を過剰と不足の間にある、状況にふさわしいあり方として捉える考え方。勇気は無謀でも臆病でもなく、何を恐れどう行動するかの判断を含む。両極端を避けるだけでなく、目的、相手、時機を考える。単なる平均や妥協ではなく、どんな行為にも善い中間があるとする主張でもない。","old_note":null,"new_note":null},{"id":"kb_954","title":"定言命法","old_summary":"自分の行動規則を誰もが従える原則にできるかを問う、カントの道徳原理。人をそれ自体で尊重し、目的達成の道具としてのみ扱うことを戒める。","new_summary":"特定の欲望を実現するための条件つき命令と区別し、無条件に従うべき道徳原理を考えるカントの概念。自分の行動規則を誰もが用いてよいか、人を単なる手段として扱っていないかを問う。目的のために例外を作る前に規則を点検する。道徳哲学上の立場であり、社会で必ず支持される行動の予測法ではない。","old_note":null,"new_note":null},{"id":"kb_955","title":"功利主義","old_summary":"行為や制度の良し悪しを、それが人々にもたらす幸福や苦痛などの結果から判断する倫理的立場。影響を受ける人全体の利益を考慮する。","new_summary":"行動や制度を、それによって生じる幸福や苦痛などの帰結から評価する倫理学の立場。自分の利益だけでなく影響を受ける人々の利益を考える。選択肢を比べるときは、誰に何が起きるかを広く見る。単なる多数決や目先の得と同義ではなく、利益の測り方や権利の扱いをめぐって議論がある。","old_note":null,"new_note":null},{"id":"kb_956","title":"無知のヴェール","old_summary":"自分の地位・能力・境遇が分からない立場に立ち、公正な社会のルールを考える思考実験。どの境遇に置かれても受け入れられる原則を問う。","new_summary":"自分が社会でどの地位、能力、境遇に置かれるかを知らない立場から、公正な制度の原則を考える思考実験。ルールを決める際、得をする側にいるという前提を外して見直す手掛かりになる。実際に全情報を捨てる方法ではなく、ロールズの正義論で用いる仮定である。公平感の心理モデルや功利主義とは区別する。","old_note":null,"new_note":null},{"id":"kb_766","title":"職務満足","old_summary":"仕事の内容・待遇・人間関係などを評価して生じる、仕事への満足や不満の感情・態度。仕事のどの側面が充実感に関わるかを捉える。","new_summary":"仕事やその側面を評価したときに生じる肯定的・否定的な態度や感情。給与だけでなく仕事の内容、関係、公正、裁量などが関わり、業績との関係は単純ではない。","old_note":null,"new_note":null},{"id":"kb_850","title":"コア・コンピタンス","old_summary":"複数の事業で活かせ、顧客に価値を与え、他社が模倣しにくい組織の中核能力。技術や技能を組み合わせる力に着目する。","new_summary":"複数事業へ展開でき、顧客価値へ寄与し、模倣されにくい組織横断的な技能・技術の束。製品ではなく再利用可能な能力を見定める。","old_note":null,"new_note":null},{"id":"kb_889","title":"タックマンモデル","old_summary":"チームの発達を、形成・混乱・規範形成・機能・散会などの段階で捉えるモデル。対立や役割調整を経て協働が育つ過程を示す。","new_summary":"小集団の発達を、形成、混乱、規範形成、機能という段階で捉えるモデル。後の論文では散会の段階が加えられた。立ち上げ時の対立を直ちに失敗とせず、役割や協働のルールを整える視点を与える。ただし、すべてのチームが同じ順序を一度だけ通るわけではなく、状況による戻りや重なりも考慮する。","old_note":null,"new_note":null},{"id":"kb_540","title":"回復理論","old_summary":"仕事やストレスで消耗した心身の資源が、休息や仕事から離れる時間によって回復するという考え。回復の機会が次の活動を支える。","new_summary":"負荷を受け続けると消耗が蓄積し、仕事から心理的・身体的に離れる時間によって資源が回復するという考え。休息は成果の反対ではなく、次の遂行を支える過程である。","old_note":null,"new_note":null},{"id":"kb_894","title":"ゴミ箱モデル","old_summary":"目標や手段が曖昧な組織では、問題・解決策・参加者・決定の機会が偶然に結びついて意思決定が生じる、と捉えるモデル。","new_summary":"組織の意思決定を、問題、解決策、参加者、選択機会という比較的独立した流れが、タイミングによって結びつく過程として捉えるモデル。目標が曖昧で、手段が不明確で、参加者が入れ替わる組織を主な対象にする。会議の結論が合理的な問題解決の順序だけで決まらない理由を考えるが、すべての組織に無秩序を勧めるものではない。","old_note":null,"new_note":null},{"id":"kb_783","title":"ネットワーク効果","old_summary":"製品やサービスの利用者が増えることで、他の利用者にとっての価値も高まる現象。連絡相手や取引相手が増える通信・仲介サービスなどで見られる。","new_summary":"利用者が増えるほど、他の利用者にとって製品やネットワークの価値が高まりうる現象。規模が増えれば常に価値が上がるわけではなく、混雑、分断、互換性も考慮する。","old_note":null,"new_note":null},{"id":"kb_806","title":"キャリア・アンカー","old_summary":"職業上の選択で譲れない、能力・動機・価値観についての自己理解。専門性、安定、自律など、自分が仕事に求める軸を捉える。","new_summary":"能力、動機、価値観について譲れない自己概念が、職業選択や異動判断の軸になるというモデル。八類型は固定診断ではなく、経験を振り返る対話の手がかりとして使う。","old_note":null,"new_note":null},{"id":"kb_423","title":"サービス・リカバリー・パラドックス","old_summary":"失敗後の優れた対応によって、失敗がなかったとき以上に顧客満足が高まることがある現象。失敗の重大さや繰り返しによって、回復の可能性は変わる。","new_summary":"失敗後の対応が非常に優れていると、失敗がなかった場合より満足や忠誠が高くなることがあるという現象。ただし常に起こるわけではなく、重大な失敗や反復する失敗には当てはまりにくい。","old_note":null,"new_note":null},{"id":"kb_402","title":"心理的安全性","old_summary":"質問・異論・失敗の報告をしても、侮辱されたり不利益を受けたりしないと、チームの中で共有されている感覚。率直な対話と学習を支える。","new_summary":"対人上のリスクを取って質問、異論、失敗を表明しても、侮辱や不利益を受けないと集団成員が共有して感じる状態。単なる仲の良さではなく、率直に学び合える条件を指す。","old_note":null,"new_note":null},{"id":"kb_290","title":"計画された偶発性理論","old_summary":"好奇心・粘り強さ・柔軟性・楽観性・リスクを取る行動によって、予期せぬ出来事をキャリアの機会へ変えるという理論。","new_summary":"予期せぬ出来事を避けるのではなく、好奇心、柔軟性、行動によってキャリア機会へ変える理論。","old_note":null,"new_note":null},{"id":"kb_765","title":"組織コミットメント","old_summary":"組織との関わりを続けようとする心理的な結びつき。愛着、離れる費用、残るべきだという義務感など、異なる理由から生じる。","new_summary":"組織に残り関わろうとする心理状態を、情緒的、継続的、規範的側面などで捉える概念。高い在籍意向と健全な貢献は同義ではなく、構成要素を分けて見る。","old_note":null,"new_note":null},{"id":"kb_893","title":"フィードラーのコンティンジェンシー理論","old_summary":"リーダーの有効性は、その人の志向と状況の組み合わせによって変わるとする理論。メンバーとの関係、課題の構造、地位に伴う権限との適合を重視する。","new_summary":"リーダーの有効性は一つの万能なスタイルではなく、比較的安定したリーダーの志向と状況の適合で決まるとする理論。リーダーとメンバーの関係、課題の構造、地位に伴う権限などを重視する。状況に合う人材配置や条件調整を考える枠組みであり、部下の成熟度に応じて行動を変える状況対応型リーダーシップとは別のモデルである。","old_note":null,"new_note":null},{"id":"kb_867","title":"プロティアン・キャリア","old_summary":"本人の価値観と主体性を軸に、環境の変化に応じて学び方や働き方を更新していくキャリア観。成功を自分にとっての納得から捉える。","new_summary":"組織ではなく本人の価値観と自己主導性を軸に、環境変化へ適応しながら成功基準を更新するキャリア観。","old_note":null,"new_note":null},{"id":"kb_940","title":"努力報酬不均衡モデル","old_summary":"仕事へ注ぐ努力に対して、賃金・承認・雇用の安定などの報酬が乏しいことが、ストレスにつながるとするモデル。","new_summary":"仕事へ投入する努力に対して、賃金、承認、安定性や昇進などの報酬が乏しい状態を、ストレスの要因として捉えるモデル。忙しさだけでなく報われ方を点検できる。個人の頑張り方に加え、待遇や評価の仕組みを検討する。病気の原因を一つに決める診断法ではなく、職務要求資源モデルとは着目する関係が異なる。","old_note":null,"new_note":null},{"id":"kb_501","title":"アウトカム評価","old_summary":"活動によって実際に生じた結果や変化を基準に、取り組みの効果を評価する方法。目的に沿って、短期と長期の変化を確かめる。","new_summary":"努力量や手続きではなく、活動によって実際に生じた結果・変化を基準に評価すること。短期成果だけを追うと副作用を見落とすため、目的に沿った複数指標が必要になる。","old_note":null,"new_note":null},{"id":"kb_941","title":"心理的エンパワーメント","old_summary":"仕事に意味があり、遂行でき、自分で選べ、結果に影響を与えられると感じること。意味・能力・自己決定・影響力の四側面で捉える。","new_summary":"仕事に意味があり、遂行でき、自分で選べ、結果へ影響を及ぼせると感じる状態を捉える枠組み。形式的に任せるだけでなく、本人が裁量と手応えを持てるかを見る。役割を渡すときは資源や情報、意思決定の余地も整える。権限委譲という制度そのものと同義ではなく、負担を増やすことだけでは高まらない。","old_note":null,"new_note":null},{"id":"kb_431","title":"境界調整","old_summary":"話題・時間・距離・連絡頻度・役割を調整し、人間関係の負担を減らす方法。自分が無理なく関われる範囲を具体的に決める。","new_summary":"関係を切るか続けるかの二択ではなく、話題、時間、距離、連絡頻度、役割を変えて負担を調整すること。関係を保ちつつ、アクセス可能な範囲を再設計する。","old_note":null,"new_note":null},{"id":"kb_552","title":"セレンディピティ","old_summary":"予期していなかった出来事から、価値ある発見や機会を見いだすこと。異なる情報に触れる行動と、その意味に気づく知識が発見を支える。","new_summary":"探していたものとは別の価値ある発見を、偶然の出来事から見いだすこと。単なる幸運ではなく、異質な情報に触れ、意味に気づき、行動へつなげる準備を含む。","old_note":null,"new_note":null},{"id":"kb_443","title":"行動的一貫性","old_summary":"発言した価値観や約束と、実際の行動が時間を通じて一致していること。一致が積み重なると、相手は言葉を信頼しやすくなる。","new_summary":"発言した価値や約束と、実際の選択や行動が時間を通じて一致している程度。一致が続くほど言葉の信頼性は高まるが、状況変化に応じた合理的な修正まで否定するものではない。","old_note":null,"new_note":null},{"id":"kb_448","title":"境界尊重テスト","old_summary":"小さな断りや距離の調整への反応を見て、相手が自分の境界を尊重するかを確かめる実務的な観察法。反応を複数の場面で見る。","new_summary":"ここでは、小さな拒否や距離の調整に相手がどう反応するかを見て、境界を尊重できる人か判断する実務的な観察法を指す。正式な心理検査ではなく、単発ではなく反復で見る。","old_note":null,"new_note":null},{"id":"kb_532","title":"作業興奮","old_summary":"作業に着手すると気持ちが課題へ向き、続けやすくなる経験を表す実務語。小さく始めることが、意欲の立ち上がりを助ける。","new_summary":"作業を始めると注意や覚醒が課題へ向き、開始前より継続しやすくなるという通俗的な説明。確立した独立理論というより、着手後に動機が生じる経験を表す実務語として扱う。","old_note":null,"new_note":null},{"id":"kb_562","title":"有限性の自覚","old_summary":"時間・体力・注意には限りがあると認識し、大切なことへ資源を振り向ける視点。選ぶものと手放すものを明確にする。","new_summary":"時間、体力、注意、人生が無限ではないと認識し、何を選び何を捨てるかを明確にすること。制約の受容が、優先順位と意味のあるコミットメントを生む。","old_note":null,"new_note":null},{"id":"kb_498","title":"意思決定支援","old_summary":"必要な情報・選択肢・判断基準を整理し、本人が納得して選べるよう助ける仕組み。比較や可視化によって判断の負担を減らす。","new_summary":"判断者に必要な情報、選択肢、基準、予測、可視化を提供し、より良い選択を助ける仕組み。意思決定そのものを奪うのではなく、認知負荷と見落としを減らす。","old_note":null,"new_note":null},{"id":"kb_554","title":"後悔最小化","old_summary":"将来の自分が何を後悔するかを想像し、長い目で納得できる選択を考える方法。短期の得失と合わせて判断の軸にする。","new_summary":"将来の自分が何を最も後悔するかを想像し、短期の損得だけでなく長期の納得を判断基準にする方法。未来の感情予測も誤るため、唯一の基準ではなく補助線として使う。","old_note":null,"new_note":null},{"id":"kb_592","title":"確率的機会","old_summary":"試行・交流・発信を重ねることで、機会と出会う回数を増やせると捉える実務的な考え。偶然が入り込む接点を広げる。","new_summary":"機会は計画どおり一度だけ現れるのではなく、試行、接触、発信を重ねるほど一定の確率で遭遇するものと捉える考え。結果を保証せず、遭遇回数を増やす。","old_note":null,"new_note":null},{"id":"kb_406","title":"暫定的な理解の提示","old_summary":"「こう感じたのかもしれない」と理解を仮の形で伝え、相手が訂正しながら話せるようにする対話の工夫。","new_summary":"ここでは「こう感じたのかもしれない」と暫定的な理解を示し、相手が否定・修正できる形で言葉を引き出す技法を指す。確立した単一の心理効果名ではなく、断定を避ける対話上の工夫である。","old_note":null,"new_note":null},{"id":"kb_1056","title":"アイゼンハワー・マトリクス","old_summary":"仕事を重要度と緊急度の二軸で分け、すぐ行う、予定する、任せる、減らすなどの対応を考える整理法。締切の近い依頼に追われるとき、将来の準備や予防の時間が押し出されていないかを確かめられる。","new_summary":"仕事を重要度と緊急度の二軸で分け、すぐ行う、予定する、任せる、減らすなどの対応を考える整理法。締切の近い依頼に追われるとき、将来の準備や予防の時間が押し出されていないかを確かめられる。まず仕事を書き出し、目的への寄与と期限を別々に評価して使う。二軸の判断は主観や役割に依存するため、他者と重要度をすり合わせる。緊急でないことが不要という意味ではなく、図に分けるだけで仕事量や権限の問題が解決するわけではない。","old_note":null,"new_note":null},{"id":"kb_1072","title":"SMART目標","old_summary":"目標を具体性、測定可能性、担当や達成可能性、現実性や関連性、期限などの観点で明確にする型。曖昧な「説明を改善する」を、対象、達成の確かめ方、実行する人、期限を含む計画へ直す。","new_summary":"目標を具体性、測定可能性、担当や達成可能性、現実性や関連性、期限などの観点で明確にする型。曖昧な「説明を改善する」を、対象、達成の確かめ方、実行する人、期限を含む計画へ直す。原提案と後の普及形ではAやRの語が異なるため、チームで意味を揃える。数値にできることだけを重要視せず、目的と指標がずれていないかを確かめる。明確な目標を作る技法であり、現実的な資源や学習なしに達成を保証する理論ではない。","old_note":null,"new_note":null},{"id":"kb_1057","title":"なぜなぜ分析（5 Whys）","old_summary":"起きた問題について「なぜ」を重ね、表面的な事象から対処可能な原因へ掘り下げる方法。納期遅れを個人の不注意で止めず、確認の工程や情報の渡し方まで調べる。","new_summary":"起きた問題について「なぜ」を重ね、表面的な事象から対処可能な原因へ掘り下げる方法。納期遅れを個人の不注意で止めず、確認の工程や情報の渡し方まで調べる。各答えを事実や現場の確認で支え、次の問いとの因果を確かめて使う。「五回」は厳密な回数規則ではない。原因が複数に分かれる問題もあり、一筋の物語で全体を説明しない。人を責める尋問や、都合のよい根本原因を想像する道具にせず、対策後の変化も検証する。","old_note":null,"new_note":null},{"id":"kb_1073","title":"GTD","old_summary":"気になる仕事を収集し、意味と次の行動を明確にし、整理し、定期的に見直して実行する個人の仕事管理法。頭に抱えた「企画」を、連絡する相手や作る資料などの具体的な次の行動へ変える。","new_summary":"気になる仕事を収集し、意味と次の行動を明確にし、整理し、定期的に見直して実行する個人の仕事管理法。頭に抱えた「企画」を、連絡する相手や作る資料などの具体的な次の行動へ変える。置き場所と見直す時点を決め、仕組みを信頼できる状態に保つことが重要になる。リストを増やすだけの方法ではなく、何を今はしないかも判断する。提唱者の実践手法であり、誰にでも同じ生産性や精神的効果が保証されるものではない。","old_note":null,"new_note":null},{"id":"kb_1080","title":"思考記録表","old_summary":"状況、感情、自動的に浮かんだ考え、その考えを支持する事実と反する事実、より釣り合った見方を記録する認知行動療法の技法。返信が遅いときに「嫌われた」と考えたなら、確認できる事実と推測を分け、他の説明を検討する。","new_summary":"状況、感情、自動的に浮かんだ考え、その考えを支持する事実と反する事実、より釣り合った見方を記録する認知行動療法の技法。返信が遅いときに「嫌われた」と考えたなら、確認できる事実と推測を分け、他の説明を検討する。無理に前向きな結論へ変えず、感情の変化も確かめる。現実の危険や不公正を否定するために使わない。セルフヘルプには限界があり、苦痛が続く場合は本人に合う専門的な支援を検討する。","old_note":null,"new_note":null},{"id":"kb_394","title":"具体的フィードバック","old_summary":"観察した行動とその結果、改善できる点を具体的に伝える方法。何を続け、次に何を変えるかが相手に分かる形で返す。","new_summary":"人物全体を評価するのではなく、観察できる行動・結果・改善点を特定して返す方法。何が良く、次に何を変えるべきかが分かるため、抽象的な称賛や批判より行動修正につながりやすい。","old_note":null,"new_note":null},{"id":"kb_1058","title":"ロジックツリー","old_summary":"大きな問いを、調べられる小さな論点や要因へ枝分かれさせて整理する方法。売上の問題を客数と単価に分け、さらに各要因を調べると、何を検証すべきか見えやすくなる。","new_summary":"大きな問いを、調べられる小さな論点や要因へ枝分かれさせて整理する方法。売上の問題を客数と単価に分け、さらに各要因を調べると、何を検証すべきか見えやすくなる。まず答える問いを明確にし、分け方の基準を揃え、枝同士の関係を確かめる。整理した図は因果関係の証明ではなく、重要な要因を仮に配置したものにすぎない。データに応じて枝を修正し、細かく分けること自体を目的にしない。","old_note":null,"new_note":null},{"id":"kb_1074","title":"ポモドーロ・テクニック","old_summary":"短い集中作業と休憩を一組として繰り返し、中断や見積もりも記録する時間管理法。代表的には25分作業し短く休む。","new_summary":"短い集中作業と休憩を一組として繰り返し、中断や見積もりも記録する時間管理法。代表的には25分作業し短く休む。着手する作業を一つ決め、タイマー中の割込みを記し、区切りで進み方を振り返る。集中のきっかけや作業量の把握には使えるが、25分が全員に最適な注意の周期という科学的法則ではない。会議、対人支援、深い集中などでは区切り方を調整する。休憩を削って回数を競う使い方にせず、作業の性質と体調を優先する。","old_note":null,"new_note":null},{"id":"kb_1059","title":"MECE","old_summary":"対象を分ける際、区分の重なりを避け、必要な範囲の抜けも避けるという点検原則。顧客を地域で分ける場合に、一人が二地域へ二重計上されず、対象外の地域が抜けないようにする。","new_summary":"対象を分ける際、区分の重なりを避け、必要な範囲の抜けも避けるという点検原則。顧客を地域で分ける場合に、一人が二地域へ二重計上されず、対象外の地域が抜けないようにする。最初に対象範囲と区分基準を決め、境界の事例を試す。実社会には複数の区分が妥当な問題もあり、無理に完全な分類へ押し込むと意味を失う。図を整えるために事実を捨てず、探索段階では仮の分類として見直す。単独で正しい結論を生む理論ではない。","old_note":null,"new_note":null},{"id":"kb_1075","title":"タイムブロッキング","old_summary":"予定表上に特定の仕事や活動を行う時間帯を割り当て、いつ取り組むかを先に決める方法。リストに「資料作成」と書くだけでなく、午前の一時間をその作業に確保する。","new_summary":"予定表上に特定の仕事や活動を行う時間帯を割り当て、いつ取り組むかを先に決める方法。リストに「資料作成」と書くだけでなく、午前の一時間をその作業に確保する。移動や休息、予備時間も含めて組み、割込みがあれば計画を更新する。時間の枠を可視化するための技法で、予定を守れなかったことを失敗と採点するものではない。タイムボックスが作業に使う時間の上限へ着目するのに対し、予定の配置と実行機会の確保に焦点を当てる。","old_note":null,"new_note":null},{"id":"kb_1060","title":"意思決定ジャーナル","old_summary":"重要な判断の時点で、選択肢、根拠、予測、確信度、気分や条件を書き残し、後から結果と照合する実践。計画を選んだときに成功の条件と予想確率を記録し、数か月後に何が当たったかを振り返る。","new_summary":"重要な判断の時点で、選択肢、根拠、予測、確信度、気分や条件を書き残し、後から結果と照合する実践。計画を選んだときに成功の条件と予想確率を記録し、数か月後に何が当たったかを振り返る。結果を知ってから理由を書き換える後知恵を点検するために使える。結果の良し悪しだけで判断過程を採点せず、当時得られた情報と偶然も考慮する。記録するだけで判断力が必ず上がるという実証法則ではなく、振り返りの質が重要である。","old_note":null,"new_note":null},{"id":"kb_1076","title":"SQ3R読書法","old_summary":"全体を見渡す、問いを立てる、読む、見ずに説明する、振り返る、の五段階で学習用の文章を読む方法。章の見出しを問いへ変え、節を読んだ後に本を閉じて答え、答えられない部分を確かめる。","new_summary":"全体を見渡す、問いを立てる、読む、見ずに説明する、振り返る、の五段階で学習用の文章を読む方法。章の見出しを問いへ変え、節を読んだ後に本を閉じて答え、答えられない部分を確かめる。読み流しを防ぎ、理解と想起を組み合わせるために使う。全ての文章へ同じ厳密な工程が必要なわけではなく、小説や速報を読む目的には調整できる。一度で完全に覚える保証はない。読む速さだけより、問いへ説明できるかを重視する。","old_note":null,"new_note":null},{"id":"kb_1061","title":"意思決定マトリクス","old_summary":"選択肢を複数の基準で並べ、必要なら重みを付けて比較する方法。仕事の候補を、費用、時間、学習機会などで比較する際に、何を重視したかを見える形にできる。","new_summary":"選択肢を複数の基準で並べ、必要なら重みを付けて比較する方法。仕事の候補を、費用、時間、学習機会などで比較する際に、何を重視したかを見える形にできる。まず必須条件を確かめ、基準と重みを選択前に決め、採点の理由を記す。重みを少し変えて順位が変わるかも確認する。数値化しても価値判断や不確実さは消えず、合計点が客観的な正解になるわけではない。基準の重複や、得点で相殺できない制約に注意する。","old_note":null,"new_note":null},{"id":"kb_1077","title":"コーネル式ノート","old_summary":"ノートを記録、手掛かりや問い、要約の領域に分け、復習で説明し直すために使う方法。講義中に主な内容を記録し、後で問いを欄外へ書き、記録部分を隠して答える。","new_summary":"ノートを記録、手掛かりや問い、要約の領域に分け、復習で説明し直すために使う方法。講義中に主な内容を記録し、後で問いを欄外へ書き、記録部分を隠して答える。最後に要点を自分の言葉でまとめ、間隔を置いて見直す。枠を引くこと自体より、問いと想起を組み合わせる点が重要になる。全ての授業や図解に同じ様式が適するとは限らず、内容に応じて変える。きれいに書き写しただけでは理解や長期記憶の保証にならない。","old_note":null,"new_note":null},{"id":"kb_475","title":"服従シグナル","old_summary":"過度な謝罪や常時の同意などが、「反論や拒否をしにくい人」という印象につながる可能性を表す実務語。やり取りの中の力関係に着目する。","new_summary":"ここでは、過度な謝罪、常時の同意、縮こまった姿勢などが「反論や拒否をしにくい人」という印象を与える可能性を指す実務語。特定のしぐさが必ず軽視を招くという法則ではない。","old_note":null,"new_note":null},{"id":"kb_1045","title":"PREP法","old_summary":"結論、理由、具体例、結論の順で短い説明を組み立てる型。会議で案を勧めるなら、まず案を述べ、その理由、具体的な利用場面を示し、最後に要点へ戻る。","new_summary":"結論、理由、具体例、結論の順で短い説明を組み立てる型。会議で案を勧めるなら、まず案を述べ、その理由、具体的な利用場面を示し、最後に要点へ戻る。話す前に四項目を一行ずつ書くと、主張と根拠のつながりを点検できる。例を出すだけで証拠になったと思わず、相手の疑問に応じて資料を補う。物語、探索的な対話、緊急連絡など、別の順序が適する場面もある。学術的な説得効果や万能な話術を証明した理論ではない。","old_note":null,"new_note":null},{"id":"kb_1078","title":"記憶の宮殿","old_summary":"よく知る場所の順序に、覚えたい情報を表すイメージを対応させ、場所をたどって取り出す記憶術。発表の要点を玄関、廊下、机へ順に置くイメージにして、発表時に道順から思い出す。","new_summary":"よく知る場所の順序に、覚えたい情報を表すイメージを対応させ、場所をたどって取り出す記憶術。発表の要点を玄関、廊下、机へ順に置くイメージにして、発表時に道順から思い出す。まず安定した経路を選び、区別しやすい像を作り、実際に想起して確認する。練習により記憶課題を助ける研究があるが、理解、判断、全般的知能が一括して高まるとは言えない。情報量や使い回しによる混同にも注意する。","old_note":null,"new_note":null},{"id":"kb_517","title":"第三者証明","old_summary":"顧客・同僚・専門家など第三者の評価や実績を、能力や信頼性の手掛かりとして示す方法。評価者の独立性や、事実を確かめられることが説得力を支える。","new_summary":"本人の自己申告ではなく、顧客、同僚、専門家、実績など第三者からの評価を能力や信頼性の証拠として用いること。情報源の独立性と検証可能性が強さを左右する。","old_note":null,"new_note":null},{"id":"kb_1046","title":"SBAR法","old_summary":"状況、背景、評価、提案または依頼を分けて伝える連絡の型。障害報告なら、今起きていること、直前の変更、把握した原因候補、相手に求める対応を順に示す。","new_summary":"状況、背景、評価、提案または依頼を分けて伝える連絡の型。障害報告なら、今起きていること、直前の変更、把握した原因候補、相手に求める対応を順に示す。医療のチーム連絡で使われる方法を一般業務へ応用した例である。事実と自分の評価を区別し、必要な情報がそろったか確認して使う。引き継ぎ全体や緊急対応の専門手順を置き換えるものではなく、聞き手の質問と理解の確認も必要になる。","old_note":null,"new_note":null},{"id":"kb_1062","title":"アフターアクションレビュー","old_summary":"活動後に、予定していたこと、実際に起きたこと、その差の理由、次に維持・改善することを関係者で確認する振り返りの方法。イベント後なら、参加者数だけでなく、準備と運営で何が機能したかを具体的な記録と照合する。","new_summary":"活動後に、予定していたこと、実際に起きたこと、その差の理由、次に維持・改善することを関係者で確認する振り返りの方法。イベント後なら、参加者数だけでなく、準備と運営で何が機能したかを具体的な記録と照合する。評価者の講評だけで終えず、参加者が事実を出し、次の行動と担当を決める。責任追及の場にすると情報が出にくくなる。米軍の学習手法を一般業務へ応用する例であり、軍事の専門手順や形式をそのまま要求するものではない。","old_note":null,"new_note":null},{"id":"kb_1079","title":"コンセプトマップ","old_summary":"概念を線と関係語で結び、知識の構造を命題として表す学習・整理法。「注意は記憶の符号化に関わる」のように、二つの概念の間にどんな関係があるかを書く。","new_summary":"概念を線と関係語で結び、知識の構造を命題として表す学習・整理法。「注意は記憶の符号化に関わる」のように、二つの概念の間にどんな関係があるかを書く。中心となる問いを決め、概念を整理し、別の枝をまたぐ関係も検討する。単語を線でつなぐだけでは関係の意味が曖昧なため、自分の言葉で説明して点検する。自由な連想を広げるマインドマップとは目的や構造が異なる。図が複雑であることを理解の深さの証拠にしない。","old_note":null,"new_note":null},{"id":"kb_1047","title":"アイ・メッセージ","old_summary":"相手の人格を評価する言い方を避け、自分が見た行動、それが及ぼす影響、自分の感じ方や必要を伝える方法。「あなたは無責任」ではなく「予定が直前に変わると準備できず困る」と具体的に述べる。","new_summary":"相手の人格を評価する言い方を避け、自分が見た行動、それが及ぼす影響、自分の感じ方や必要を伝える方法。「あなたは無責任」ではなく「予定が直前に変わると準備できず困る」と具体的に述べる。事前に事実と評価を分け、伝えた後は相手の事情も聞く。主語を私にするだけで非難が消えるわけではなく、「私はあなたが悪いと思う」は実質的に評価のままである。深刻な権力差や危険な関係では、この話し方だけで解決を期待しない。","old_note":null,"new_note":null},{"id":"kb_1063","title":"KPT振り返り","old_summary":"続けたいこと、問題、次に試すことの三つに分けて活動を振り返る方法。チームで一週間の作業を思い出し、うまくいった連絡はKeep、滞った確認はProblem、次週の短い確認会をTryとして整理する。","new_summary":"続けたいこと、問題、次に試すことの三つに分けて活動を振り返る方法。チームで一週間の作業を思い出し、うまくいった連絡はKeep、滞った確認はProblem、次週の短い確認会をTryとして整理する。具体的な出来事を出し、試すことに担当と見直す時点を付ける。問題の一覧を作るだけでなく、続ける行動も残す点が特徴になる。Tryを増やしすぎると実行できなくなるため絞る。単独の学術理論ではなく、議論を支える実務上の型である。","old_note":null,"new_note":null},{"id":"kb_1048","title":"SBIフィードバック","old_summary":"特定の状況、その場で観察した行動、その影響の三点でフィードバックする技法。「今朝の打合せで、説明中に何度も質問が重なり、最後の確認ができなかった」のように具体化する。","new_summary":"特定の状況、その場で観察した行動、その影響の三点でフィードバックする技法。「今朝の打合せで、説明中に何度も質問が重なり、最後の確認ができなかった」のように具体化する。伝える前に日時や場面を確かめ、行動と推測した意図を分ける。本人の意図を聞くこともできるが、意図が良ければ影響が消えるわけではない。人格評価や一方的な断罪を避ける補助であり、三点を述べれば必ず相手が納得するというものではない。","old_note":null,"new_note":null},{"id":"kb_1064","title":"RACIマトリクス","old_summary":"仕事ごとに、実行担当、最終的な説明責任をもつ人、相談先、情報共有先を整理する表。資料作成なら、書く人、承認する人、助言を求める人、完成を知らせる人を分けて合意する。","new_summary":"仕事ごとに、実行担当、最終的な説明責任をもつ人、相談先、情報共有先を整理する表。資料作成なら、書く人、承認する人、助言を求める人、完成を知らせる人を分けて合意する。曖昧な引き継ぎや承認待ちを見つけるため、作業と意思決定の単位を揃えて作る。表を作るだけで権限が発生するわけではなく、本人の認識、負荷、実際の承認ルールを確認する。相談先を増やしすぎず、変更時には更新する。職務上の権限や責任を勝手に変更する道具ではない。","old_note":null,"new_note":null},{"id":"kb_1049","title":"動機づけ面接","old_summary":"変化について迷いがある人と、協働し、本人の理由や価値を引き出しながら話す面接の方法。始めたい気持ちと続ける不安の両方を聞き、本人がどうしたいかを確かめる。","new_summary":"変化について迷いがある人と、協働し、本人の理由や価値を引き出しながら話す面接の方法。始めたい気持ちと続ける不安の両方を聞き、本人がどうしたいかを確かめる。開かれた質問、是認、聞き返し、要約などを、相手の自律性を尊重する姿勢とともに使う。こちらの望む方向へ巧みに誘導する質問集ではない。専門的実践には学習と訓練が必要で、一般の会話での応用が治療と同じ効果をもつとは限らない。","old_note":null,"new_note":null},{"id":"kb_1065","title":"ステークホルダーマップ","old_summary":"活動の影響を受ける人や関わる人を挙げ、関心、影響力、関係、必要な対話を整理する方法。新しい運用を導入するなら、決裁者だけでなく使う人や負担を受ける人も含める。","new_summary":"活動の影響を受ける人や関わる人を挙げ、関心、影響力、関係、必要な対話を整理する方法。新しい運用を導入するなら、決裁者だけでなく使う人や負担を受ける人も含める。二軸の図や関係図を使い、分からないことは本人への確認事項として残す。影響力の低い人を無視するための順位表ではない。分類は仮説なので、状況や意見の変化に応じて更新する。図を作るだけで合意が得られるわけではなく、実際の対話と意思決定が必要である。","old_note":null,"new_note":null},{"id":"kb_1050","title":"ティーチバック法","old_summary":"説明した内容を相手自身の言葉で述べてもらい、こちらの伝え方が十分だったかを確かめる方法。新しい手順を伝えた後、「説明が分かりにくくなかったか確認したいので、次にすることを教えてください」と頼む。","new_summary":"説明した内容を相手自身の言葉で述べてもらい、こちらの伝え方が十分だったかを確かめる方法。新しい手順を伝えた後、「説明が分かりにくくなかったか確認したいので、次にすることを教えてください」と頼む。理解が違っていれば説明を変え、もう一度確認する。相手の知識を試す試験や、原文を暗唱させる方法ではない。医療での利用を一般業務へ応用する場合も、相手を責めない言い方と、説明する側の責任を明確にする。","old_note":null,"new_note":null},{"id":"kb_1066","title":"PEST分析","old_summary":"政治・制度、経済、社会、技術の四領域から、活動の外部環境を整理する方法。事業を考えるなら規制、費用、生活習慣、技術の変化を挙げ、それぞれがどう影響するかを検討する。","new_summary":"政治・制度、経済、社会、技術の四領域から、活動の外部環境を整理する方法。事業を考えるなら規制、費用、生活習慣、技術の変化を挙げ、それぞれがどう影響するかを検討する。情報の日付と根拠を記し、影響が大きく不確実な条件は複数の見通しに分ける。分類を埋めるだけでは将来予測にならず、因果や重要度も別に確かめる。法律と環境を分けるPESTLEなどの拡張もあるが、同じ項目を二重に数えたり、拡張全体を同義語にしたりしない。","old_note":null,"new_note":null},{"id":"kb_1051","title":"クローズドループ・コミュニケーション","old_summary":"送り手が情報を伝え、受け手が受領内容を返し、送り手がそれを確かめることで連絡の輪を閉じる方法。作業依頼なら「Aを15時までに」へ受け手が内容を返し、送り手が一致を確認する。","new_summary":"送り手が情報を伝え、受け手が受領内容を返し、送り手がそれを確かめることで連絡の輪を閉じる方法。作業依頼なら「Aを15時までに」へ受け手が内容を返し、送り手が一致を確認する。重要な数値や役割を伝えるときに、確認する情報を絞って使う。受け手がうなずいただけでは、同じ理解になったかは分からない。確認の負担と重要度を考慮し、通常の対話をすべて機械的な復唱にしない。専門現場では既定の手順を優先する。","old_note":null,"new_note":null},{"id":"kb_1067","title":"AIDAモデル","old_summary":"注意、関心、欲求、行動の観点で広告や販売の働きかけを整理する古典的モデル。案内を見てもらえているのに申込みが少ない場合、内容への関心や必要性、手続きの障壁を分けて検討できる。","new_summary":"注意、関心、欲求、行動の観点で広告や販売の働きかけを整理する古典的モデル。案内を見てもらえているのに申込みが少ない場合、内容への関心や必要性、手続きの障壁を分けて検討できる。各段階で何を伝え、どう確かめるかを明確にして使う。人が必ずこの順序だけで購入するという実証法則ではなく、比較、再訪、口コミなどで前後することもある。注意を集めたことと価値を提供したことを混同せず、誤解や過剰な欲求をあおる説明にしない。","old_note":null,"new_note":null},{"id":"kb_1052","title":"STAR法","old_summary":"状況、課題、自分の行動、結果の順で経験を説明する型。面接で「調整が得意」と述べる代わりに、期限が重なった状況、担当した課題、行った調整、その結果を具体的に話す。","new_summary":"状況、課題、自分の行動、結果の順で経験を説明する型。面接で「調整が得意」と述べる代わりに、期限が重なった状況、担当した課題、行った調整、その結果を具体的に話す。準備では各項目を書き、チームの成果と自分の行動を分け、結果に不確実さがあれば明示する。全ての経験を成功談へ整える必要はなく、失敗から学んだ点も説明できる。説得力のための構成技法であり、結果だけから行動の質が証明されるわけではない。","old_note":null,"new_note":null},{"id":"kb_1068","title":"JTBD","old_summary":"人がある状況で成し遂げたい進歩を「ジョブ」として捉え、製品やサービスを選ぶ理由を理解する枠組み。移動中の朝食を選ぶ人なら、栄養だけでなく、手を汚さず移動時間を過ごす必要が関わる場合がある。","new_summary":"人がある状況で成し遂げたい進歩を「ジョブ」として捉え、製品やサービスを選ぶ理由を理解する枠組み。移動中の朝食を選ぶ人なら、栄養だけでなく、手を汚さず移動時間を過ごす必要が関わる場合がある。実際の選択の前後を聞き、状況、障害、代替手段を整理する。属性や機能の一覧を捨てる意味ではなく、それだけで説明しきれない理由を探す。ジョブは職務名のことではなく、面接からの解釈も仮説として行動や他の資料と照合する。","old_note":null,"new_note":null},{"id":"kb_1053","title":"SCQA","old_summary":"共有できる状況、そこに生じた変化や問題、答えるべき問い、答えの順で説明を組み立てる型。提案書なら、現状の運用、増えた負担、何を変えるべきか、提案という流れにする。","new_summary":"共有できる状況、そこに生じた変化や問題、答えるべき問い、答えの順で説明を組み立てる型。提案書なら、現状の運用、増えた負担、何を変えるべきか、提案という流れにする。相手が何を既に知り、どの問いに答えてほしいかを確認してから使う。問題を大げさに作って提案を正当化せず、状況と根拠を照合する。Mintoの文章構造の考え方に沿う実務技法であり、探索中の議論や感情の共有には別の構成が適する場合もある。","old_note":null,"new_note":null},{"id":"kb_1069","title":"STP分析","old_summary":"市場や利用者を意味のある違いで分け、対象を選び、その対象にとってどの価値で比較されたいかを定める方法。講座を作るなら学習目的や制約で利用者を分け、対象を絞り、他の手段との違いを明確にする。","new_summary":"市場や利用者を意味のある違いで分け、対象を選び、その対象にとってどの価値で比較されたいかを定める方法。講座を作るなら学習目的や制約で利用者を分け、対象を絞り、他の手段との違いを明確にする。分類は調査で確かめ、対象の需要と自分が提供できるものを照合する。人を固定した属性へ押し込めたり、選んだ市場なら必ず成功すると考えたりしない。売り手の希望だけで位置づけは決まらず、利用者の認識と競合も必要である。","old_note":null,"new_note":null},{"id":"kb_1054","title":"SPIN話法","old_summary":"状況、問題、その問題の影響、解決による価値を尋ねる質問の枠組み。業務の相談なら現在の手順を聞き、困る点、その影響、改善できた場合の意味を相手と確かめる。","new_summary":"状況、問題、その問題の影響、解決による価値を尋ねる質問の枠組み。業務の相談なら現在の手順を聞き、困る点、その影響、改善できた場合の意味を相手と確かめる。単に質問を順番に読み上げず、既に分かる状況は調べ、必要な問いに絞る。営業研究からの方法だが、どの商談にも同じ順序や成果が保証されるわけではない。相手の不安を意図的に増幅したり、合わない提案へ誘導したりするために使わない。","old_note":null,"new_note":null},{"id":"kb_1070","title":"マーケティングの4P","old_summary":"製品、価格、流通、販促の四観点から、顧客へ価値を届ける施策の組合せを考える枠組み。良い教材を作っても、価格が合わず、入手方法が分かりにくければ利用されにくい。","new_summary":"製品、価格、流通、販促の四観点から、顧客へ価値を届ける施策の組合せを考える枠組み。良い教材を作っても、価格が合わず、入手方法が分かりにくければ利用されにくい。誰にどの価値を届けるかを先に決め、四項目が矛盾していないかを点検する。各項目を埋めれば売れるという公式ではなく、顧客の反応や費用を調べて見直す。サービス等では拡張モデルもあり、四項目だけで事業全体や顧客経験のすべてを説明しない。","old_note":null,"new_note":null},{"id":"kb_1055","title":"I-PASS","old_summary":"重症度、患者の要約、実施事項、状況認識と対応計画、受け手による要約を整理する医療の引き継ぎの型。一般業務へ翻案するなら、緊急度、現状、次の作業、起こりうる問題と対処、受け手の理解確認に置き換えて考える。","new_summary":"重症度、患者の要約、実施事項、状況認識と対応計画、受け手による要約を整理する医療の引き継ぎの型。一般業務へ翻案するなら、緊急度、現状、次の作業、起こりうる問題と対処、受け手の理解確認に置き換えて考える。担当交代の前に未完事項と条件付きの対応を明文化し、最後に受け手が要点を返す。一般業務の翻案が医療と同じ成果を保証するわけではない。医療での利用は所属機関の正式な手順と訓練に従う。","old_note":null,"new_note":null},{"id":"kb_1071","title":"カスタマージャーニーマップ","old_summary":"利用者が目的を達成する過程を、行動、考え、感情、接点などとともに時系列で可視化する方法。申込みの途中で離れる理由を探すなら、案内を知る前から利用後までの経験を調べ、困る地点を整理する。","new_summary":"利用者が目的を達成する過程を、行動、考え、感情、接点などとともに時系列で可視化する方法。申込みの途中で離れる理由を探すなら、案内を知る前から利用後までの経験を調べ、困る地点を整理する。対象の人物と場面、現状か将来像か、調査済みか仮説かを明示して作る。社内の想像だけで利用者の事実としない。図の美しさより、証拠のある課題と次の検証を決めることを重視する。すべての人が同じ一本道を通るわけではない。","old_note":null,"new_note":null},{"id":"kb_902","title":"エリクソンの心理社会的発達理論","old_summary":"生涯にわたる発達を、信頼・自律・自己同一性・親密性など、他者や社会との関係で生じる課題から捉える理論。課題は後の時期にも再び現れる。","new_summary":"人の生涯発達を、基本的信頼、自律性、アイデンティティ、親密性など、各段階での心理社会的な課題から捉える理論。自己の形成を幼少期だけに限定せず、他者や社会との関係の中で理解する。年齢だけで発達を判定するための尺度ではなく、各課題は後の時期にも再び問題になり得る。文化や生活条件による違いも考慮する。","old_note":null,"new_note":null},{"id":"kb_917","title":"脳の可塑性","old_summary":"経験や学習に応じて、脳・神経系の働きや構造が変化する性質。技能の習得や学び直しを支え、変化の仕方は年齢・課題・練習の条件によって異なる。","new_summary":"経験や学習、環境の変化に応じて、神経系の働きや構造が変わりうる性質。成人でも技能練習に伴う変化が観察され、学び直しの可能性を支える。反復だけでなく課題、休息、環境を考える手掛かりになる。ただし変化の範囲には条件があり、努力すれば何でも治る、何歳でも同じ速度で習得できるという意味ではない。","old_note":null,"new_note":null},{"id":"kb_059","title":"自己カテゴリー化理論","old_summary":"状況に応じて自分を集団の一員として認識し、その集団の規範や価値観に沿って行動する過程を説明する理論。","new_summary":"状況に応じて自分を個人ではなく集団の一員として捉え、集団規範に沿って行動する過程を説明する理論。","old_note":null,"new_note":null},{"id":"kb_906","title":"PERMAモデル","old_summary":"幸福や充実を、肯定的感情・没頭・関係性・意味・達成の五つの要素から捉えるモデル。生活のどの側面が満たされているかを整理する。","new_summary":"ウェルビーイングを、肯定的感情、没頭、関係性、意味、達成という五つの要素から捉えるモデル。楽しい気分だけを幸福の尺度にせず、生活のどこが充実し、どこが不足しているかを振り返る枠組みになる。五つを同じ重みで満たす義務や、個人の価値を採点する尺度ではない。各要素の独立性や測定方法は研究上の検討対象である。","old_note":null,"new_note":null},{"id":"kb_918","title":"ヘッブの法則","old_summary":"繰り返し一緒に活動する神経細胞の間では、結びつきが強まるという学習の仮説。経験による神経回路の変化を説明する基礎となった。","new_summary":"ある神経細胞が別の細胞の活動を繰り返し助けると、その結びつきが強まるとする学習の仮説。経験を神経回路の変化として説明する基礎となった。複数の要素を一緒に学ぶ見方につながるが、日常の反復すべてが同じ神経機構で起きるわけではない。神経可塑性全体と同義にはせず、仮説と観察された現象を分ける。","old_note":null,"new_note":null},{"id":"kb_008","title":"自己開示の返報性","old_summary":"自分が考えや経験を適度に話すと、相手も同じ程度に自分のことを話しやすくなる傾向。やり取りを重ねながら親密さが深まる。","new_summary":"自分の考えや経験を適度に開示すると、相手も同程度の自己開示を返しやすくなる傾向。親密さは一方的ではなく段階的に深まる。","old_note":null,"new_note":null},{"id":"kb_873","title":"変化盲","old_summary":"場面の切り替えや短い遮蔽が挟まると、大きな変化でも見落とすことがある現象。変わった箇所を知覚するには、前後の情報への注意と比較が必要になる。","new_summary":"場面の切り替えや短い遮蔽を挟むと、前後で大きな変化があっても検出しにくくなる現象。見える情報をすべて精密に保持し、比較しているわけではないことを示す。改訂箇所を明示したり、変更前後を並べたりすると確認しやすい。予期しない対象そのものを見落とす非注意性盲目とは別の現象である。","old_note":null,"new_note":null},{"id":"kb_905","title":"キャノン＝バード理論","old_summary":"感情を引き起こす刺激に対し、感情の経験と身体反応が並行して生じるとする歴史的な情動理論。","new_summary":"情動を生む刺激に対して、感情経験と身体反応が並行して生じるとする歴史的な理論。身体反応の知覚から感情が生じるとするジェームズ＝ランゲ理論への批判から発展した。感情と身体の関係を比較するための基礎になるが、当時の神経機構の説明を、現在の脳科学がそのまま確定した事実として採用しているわけではない。","old_note":null,"new_note":null},{"id":"kb_910","title":"生涯発達理論","old_summary":"発達を生涯にわたる変化として捉え、成長と喪失、個人と環境の相互作用を考える枠組み。人生の各時期に異なる変化と適応がある。","new_summary":"発達を子どもの成長だけでなく、生涯にわたる変化として捉える枠組み。能力や役割には伸びる側面と失われる側面が同時にあり、環境や歴史によって経路も変わる。年齢だけで可能性を決めず、今ある資源と学び直せる範囲を見る。あらゆる能力が無制限に向上するという意味ではない。","old_note":null,"new_note":null},{"id":"kb_921","title":"睡眠と記憶の固定化","old_summary":"睡眠中の処理を通じて、学んだ記憶が安定し、既存の知識と結びついていく過程。効果は学習内容や睡眠の条件によって変わる。","new_summary":"学習した記憶が睡眠中の処理を通じて安定し、既存の知識と結びついていく過程。学んだ直後の成績と、後日使える状態を分けて考える助けになる。練習と睡眠の両方を学習計画に含める。効果は記憶の種類や睡眠の条件によって異なり、眠るだけで未学習の内容を覚えられるという意味ではない。","old_note":null,"new_note":null},{"id":"kb_911","title":"選択・最適化・補償モデル","old_summary":"大切な目標を選び、その達成に力を集中し、失った手段を別の方法で補うという適応モデル。限られた資源で重要な活動を維持する。","new_summary":"限られた資源の中で、重視する目標を選び、その遂行を磨き、失われた手段を別の方法で補うという適応モデル。例えば活動を絞って練習し、補助道具を使って続ける。単なる諦めや効率化ではなく、本人にとって大切な活動を維持する見方である。補償がすべての損失を解消するとは限らない。","old_note":null,"new_note":null},{"id":"kb_922","title":"アロスタティック負荷","old_summary":"ストレスへの身体の調整が繰り返されることで、心身に蓄積する負担。短期には役立つ反応も、長く続くと健康上のコストを生む。","new_summary":"ストレスに対処する身体の調整が繰り返され、終わりにくくなることで蓄積する負担を捉える概念。短期の適応に役立つ反応でも、長期にはコストを持ちうる。頑張る時間だけでなく回復や環境の負荷を見る手掛かりになる。主観的な疲れそのものや一つの診断名と同義ではなく、単一の指標だけで判定しない。","old_note":null,"new_note":null},{"id":"kb_1012","title":"実行機能","old_summary":"目標に沿って思考や行動を調整するための機能群。抑制、作業記憶、認知的柔軟性などを含み、必要な情報を保ちながら不要な反応を抑え、状況に応じて切り替える働きとして説明される。","new_summary":"目標に沿って思考や行動を調整するための機能群。抑制、作業記憶、認知的柔軟性などを含み、必要な情報を保ちながら不要な反応を抑え、状況に応じて切り替える働きとして説明される。作業を小分けにし、手順を外に書くことは負荷を軽くする助けになる。計画が進まない理由を意志の弱さだけに求めない視点になるが、単一の能力や診断ではない。睡眠、ストレス、課題、発達段階などでも発揮のされ方が変わる。","old_note":null,"new_note":null},{"id":"kb_738","title":"エビングハウスの忘却曲線","old_summary":"学習後の記憶は初めに速く失われ、時間がたつほど忘却の進み方が緩やかになることを表す曲線。記憶の保たれ方は教材や復習の条件で変わる。","new_summary":"学習後の記憶は初期に急速に失われ、その後ゆるやかになるという保持の時間変化。曲線の形は材料、個人、想起条件で変わり、固定の忘却率ではない。","old_note":null,"new_note":null},{"id":"kb_869","title":"プロテウス効果","old_summary":"仮想空間で使うアバターの外見に沿って、利用者の振る舞いが変わることがある現象。自己表象と対人距離・自己開示・交渉行動などの関係を扱う。","new_summary":"仮想空間で使うアバターの外見や特徴に沿って、利用者の振る舞いが変わる現象。初期研究では、アバターの魅力や身長と、対人距離、自己開示、交渉行動との関係が調べられた。自己表象が行動へ影響する手がかりになるが、現実の服装や外見を変えれば人格全体が変わるという主張ではない。","old_note":null,"new_note":null},{"id":"kb_888","title":"社会的インパクト理論","old_summary":"他者から受ける影響の強さを、影響源の力・近さ・人数から説明する理論。影響を受ける人が複数いると、その影響は分散しうる。","new_summary":"他者から受ける影響の大きさを、影響源の強さ、心理的・物理的な近さ、人数などから捉える理論。影響を受ける側が複数いる場合の分散も考える。単に人数が多ければよいという説明ではなく、相手の地位や距離も重要になる。同調や責任の分散を比較する枠組みであり、それぞれの現象の詳しい仕組みを置き換えるものではない。","old_note":null,"new_note":null},{"id":"kb_912","title":"社会情動的選択性理論","old_summary":"残された時間をどう感じるかによって、人との関わりで重視する目標が変わるという理論。時間が限られると、意味ある関係や感情的な充実を優先しやすい。","new_summary":"残された時間をどう感じるかによって、人との関わりで優先する目標が変わるという理論。時間が広く開けていると知識や新しい縁を、限られていると意味ある関係や感情的充足を重視しやすい。暦年齢だけでなく時間の捉え方を見る。高齢者が必ず交流を減らすという法則ではない。","old_note":null,"new_note":null},{"id":"kb_459","title":"規範的影響","old_summary":"集団に受け入れられたい、拒絶されたくないという気持ちから、周囲の意見や行動に合わせること。内心では異論があっても、公の場では同調する場合がある。","new_summary":"正しさへの確信ではなく、受け入れられたい、拒絶されたくないという動機から集団に合わせる影響。公の場では同調しても、私的な信念までは変わらないことがある。","old_note":null,"new_note":null},{"id":"kb_879","title":"検索誘導性忘却","old_summary":"ある情報を繰り返し思い出すことで、それと関連する別の情報を思い出しにくくなることがある現象。検索の練習範囲が、後の記憶の取り出しやすさに影響する。","new_summary":"ある情報を繰り返し思い出すと、関連しているが練習しなかった情報を後で思い出しにくくなることがある現象。原著では同じカテゴリー内の一部だけを検索練習した後、未練習項目の再生が低下した。検索練習そのものを否定する結果ではなく、練習する範囲や手がかりも考える必要があることを示す。","old_note":null,"new_note":null},{"id":"kb_883","title":"モラル・ライセンシング","old_summary":"過去の善行や「自分は道徳的だ」という感覚が、その後の問題ある行動を許す理由になることがある現象。自分の実績を免罪符にする判断を説明する。","new_summary":"過去の善い行動や、自分は道徳的だという感覚が、その後の問題ある選択を許容する理由になることがある現象。自分の実績を免罪符にする判断を説明する。次の行動を個別に点検する視点が役立つが、善行の後には一貫した善行が続くこともあり、必ず悪い行動へ向かうわけではない。経済学のモラルハザードとは仕組みが異なる。","old_note":null,"new_note":null},{"id":"kb_913","title":"成人形成期","old_summary":"青年期と安定した成人の役割との間で、仕事・恋愛・価値観を探索する時期を捉える概念。経験する時期や長さは、文化や生活条件によって異なる。","new_summary":"青年期を過ぎても成人の役割が定まらない時期を、仕事、恋愛、価値観を探索する発達上の期間として捉える考え方。進路の揺れを直ちに未熟さと決めず、試行の機会と生活条件を見直す手掛かりになる。教育や経済、文化に左右される枠組みで、すべての人が同じ年齢で経験する段階ではない。","old_note":null,"new_note":null},{"id":"kb_263","title":"成長マインドセット","old_summary":"能力は学習・工夫・支援によって伸ばせると捉える信念。失敗を、方法を変えたり学び直したりする手掛かりとして受け止めやすくなる。","new_summary":"能力は固定されたものではなく、努力、戦略、支援によって伸ばせると捉える信念。","old_note":null,"new_note":null},{"id":"kb_597","title":"利用可能性ヒューリスティック","old_summary":"思い出しやすい事例をもとに、出来事の頻度や起こりやすさを判断する傾向。印象に残る失敗談やニュースは、実際の確率以上に重く見積もられやすい。","new_summary":"思い出しやすい事例ほど、実際より頻繁・重大・起こりやすいと見積もりやすい判断の近道。印象的な失敗談やニュースは、確率そのものではない。","old_note":null,"new_note":null},{"id":"kb_736","title":"フロー理論","old_summary":"自分の技能と挑戦の難しさが高い水準で釣り合うと、活動へ深く没頭しやすいという理論。明確な目標や、進み具合が分かることも関わる。","new_summary":"技能と挑戦の水準がともに高く釣り合うと、行為への深い没入と明確な手応えが生じやすいという理論。没入は幸福や高成果と同義ではなく、活動内容と回復も考慮する。","old_note":null,"new_note":null},{"id":"kb_914","title":"生態学的システム理論","old_summary":"人の発達を、家庭・学校・職場・制度・文化など、重なり合う環境との関係から捉える理論。身近な環境同士のつながりも発達に影響する。","new_summary":"発達を、家庭や学校といった身近な環境、そのつながり、職場や制度、文化などが重なって作用する過程として見る理論。本人の努力だけで説明できない変化を、環境の層ごとに考えられる。困り事を個人の性格に還元せず、支援先や環境調整を探す。後の生物生態学的モデルと完全な同義ではない。","old_note":null,"new_note":null},{"id":"kb_583","title":"固定的自己観","old_summary":"能力や人格を変わりにくい性質と捉え、一度の結果を自分全体の評価に結びつける見方。失敗を自己否定として受け止めやすくなる。","new_summary":"能力や人格を変わりにくい本質と捉え、一度の結果を「自分はこういう人間だ」という総合評価へ結びつける見方。失敗を学習情報ではなく自己の証明として受け取りやすい。","old_note":null,"new_note":null},{"id":"kb_724","title":"ビッグ・ファイブ","old_summary":"性格の傾向を、開放性・誠実性・外向性・協調性・神経症傾向の五つの連続した尺度で捉えるモデル。","new_summary":"人格特性を開放性、誠実性、外向性、協調性、神経症傾向の五次元で記述するモデル。人を五つの型へ分類する診断ではなく、連続的な傾向を比較する枠組みである。","old_note":null,"new_note":null},{"id":"kb_916","title":"流動性知能・結晶性知能","old_summary":"新しい問題を解く流動性知能と、経験から蓄えた知識を使う結晶性知能を区別する枠組み。両者は年齢や学習によって異なる変化を示す。","new_summary":"新しい課題の関係を見抜いて解く能力と、経験を通じて蓄積した知識を使う能力を区別する知能の枠組み。未知の道具の操作と、熟知した仕事の判断では求められる資源が異なる。年齢に伴う変化も一つの能力だけで測らない。二種類ですべての能力を説明できるわけではなく、個人差も大きい。","old_note":null,"new_note":null},{"id":"kb_1009","title":"コールバーグの道徳性発達理論","old_summary":"道徳判断の理由づけが、罰の回避、周囲の承認、社会のルール、普遍的な原則などへ発達すると捉える段階理論。何を根拠に正しいと考えるかに着目する。","new_summary":"道徳判断を、どの結論を選ぶかだけでなく、その理由づけの発達から捉える段階理論。罰を避けるため、周囲に認められるため、原則を守るためなど、同じ行為でも説明の根拠は異なる。意見の違いを話し合う際、何を理由に判断したのかを聞く視点になる。実際の行動の善悪や人間の価値を段階で採点するものではない。文化、ジェンダー、課題の作り方、理由づけと実行の差に関する批判があり、固定した普遍的診断にはしない。","old_note":null,"new_note":null},{"id":"kb_1010","title":"気質理論","old_summary":"早期から見られる反応の強さや注意、自己調整などの個人差を、生物的基盤と発達・環境の相互作用から捉える理論群。新しい場所へすぐ近づく子と、様子を見てから参加する子では、安心して試せる支援も違う。","new_summary":"早期から見られる反応の強さや注意、自己調整などの個人差を、生物的基盤と発達・環境の相互作用から捉える理論群。新しい場所へすぐ近づく子と、様子を見てから参加する子では、安心して試せる支援も違う。本人を怠惰やわがままと決めず、反応の特徴と環境の合い方を見る手掛かりになる。気質は将来の性格や成功を固定しない。ThomasとChess、Rothbartらでモデルが異なり、特定の類型をすべての人へ当てはめない。","old_note":null,"new_note":null},{"id":"kb_877","title":"ソースモニタリング","old_summary":"記憶している情報が、実体験・他者の話・想像などのどこから来たかを判断する過程。内容が鮮明でも、出所を取り違えることがある。","new_summary":"覚えている情報が、実際の経験、他者の発言、想像などのどこから来たのかを判断する過程。内容が鮮明でも、その出所を正しく思い出せるとは限らない。見聞きした事実と推測を記録時に分けると、後から出所を確かめやすい。誤情報効果などを理解する枠組みだが、それら個別の記憶現象と同一ではない。","old_note":null,"new_note":null},{"id":"kb_1011","title":"遅延満足","old_summary":"目の前の小さな報酬をすぐ受け取る代わりに、後のより大きな報酬を待つこと。今遊ぶ代わりに、準備を終えてから長く遊ぶような場面で考えられる。","new_summary":"目の前の小さな報酬をすぐ受け取る代わりに、後のより大きな報酬を待つこと。今遊ぶ代わりに、準備を終えてから長く遊ぶような場面で考えられる。待てるかどうかは注意の向け方だけでなく、約束が守られる見込みや家庭・生活の条件にも左右される。実践では誘惑を見えにくくし、待つ理由と予定を明確にする。幼少期の一つの課題だけで人生の成功が決まるという解釈は不適切で、後の成績との関連には背景要因を考慮する必要がある。","old_note":null,"new_note":null},{"id":"kb_731","title":"ステレオタイプ脅威","old_summary":"自分の所属集団への否定的な固定観念を意識すると、評価への不安や注意の負担が増し、課題の成績が下がることがある現象。","new_summary":"所属集団への否定的ステレオタイプを意識すると、評価場面で負担が増して成績が低下しうる現象。個人能力の欠如ではなく、課題の提示や環境との相互作用として扱う。","old_note":null,"new_note":null},{"id":"kb_421","title":"一貫性ヒューリスティック","old_summary":"相手の言動が一貫していると、予測しやすく信頼できると判断しやすい傾向。一貫性が、相手を評価する手掛かりになる。","new_summary":"相手の言動が時間や場面をまたいで一貫していると、予測しやすく信頼できると判断しやすい傾向。実際の誠実さを保証するものではないが、認知負荷を下げる手掛かりになる。","old_note":null,"new_note":null},{"id":"kb_727","title":"インポスター現象","old_summary":"実績があっても自分の能力を認められず、成功を運や過剰な努力のおかげと考え、評価が誤りだと知られることを恐れる経験。","new_summary":"実績があっても自分の能力を信じられず、成功を運や過剰努力へ帰属して露見を恐れる経験。正式な精神疾患名ではなく、環境や所属集団の影響も含めて理解する必要がある。","old_note":null,"new_note":null},{"id":"kb_426","title":"関係維持行動","old_summary":"肯定・率直な対話・役割分担・共同活動などによって、人間関係を続けやすくする行動。日々の小さな関わりが関係の安定を支える。","new_summary":"関係を続けるために行う、肯定、率直さ、役割分担、共同活動、社会的ネットワークの活用などの行動。関係は自然に維持されるのではなく、日常の小さな運用によって支えられる。","old_note":null,"new_note":null},{"id":"kb_207","title":"安全行動","old_summary":"恐怖や不安を和らげるために行う、過剰な確認や回避などの行動。一時的に安心しても、安全を確かめる学習の機会を失い、不安が続くことがある。","new_summary":"不安を避けるために行う確認、逃避、過剰準備などの行動。短期的には安心しても、危険ではないという学習を妨げる。","old_note":null,"new_note":null},{"id":"kb_039","title":"関係破綻・修復モデル","old_summary":"人間関係が不満・距離化・対立を経て、修復や解消へ進む過程を捉えるモデル。小さな変化の積み重なりに着目する。","new_summary":"関係が不満、距離化、対立、修復または解消へ進む過程を捉えるモデル。問題は突然ではなく、小さな変化の蓄積として進行する。","old_note":null,"new_note":null},{"id":"kb_044","title":"帰属的葛藤","old_summary":"相手の問題行動を性格や悪意のせいだと解釈し、その解釈が対立を深めてしまうこと。互いの原因の捉え方が衝突を増幅する。","new_summary":"問題行動の原因を、状況ではなく相手の性格や悪意に帰属することで対立が深まる現象。","old_note":null,"new_note":null},{"id":"kb_831","title":"記憶の再固定化","old_summary":"思い出した記憶が一時的に不安定になり、再び保存される際に新しい情報の影響を受けうる過程。記憶が更新される条件を扱う。","new_summary":"想起により不安定化した記憶が、再び保存される過程で更新されうるという研究領域。想起しただけで自在に書き換えられるわけではない。","old_note":null,"new_note":null},{"id":"kb_732","title":"脱個人化","old_summary":"匿名性や集団への没入によって個人としての自己意識が弱まり、その場の規範や集団の行動に沿いやすくなる状態。","new_summary":"匿名性、集団への没入、責任感の低下などにより、個人としての自己認識や通常の規範が弱まる状態。必ず反社会的になるのではなく、その場で顕著な集団規範に沿いやすくなる。","old_note":null,"new_note":null},{"id":"kb_565","title":"ストレス緩衝仮説","old_summary":"他者の支えが、強いストレスによる心身への悪影響を和らげるという仮説。ストレスの種類に合った支援が緩衝材として働く。","new_summary":"社会的支援は常に同じ効果を持つのではなく、強いストレス下でその悪影響を和らげる緩衝材として特に働くという仮説。支援内容とストレスの種類の適合が影響する。","old_note":null,"new_note":null},{"id":"kb_740","title":"フォン・レストルフ効果","old_summary":"並んだ項目の中で、一つだけ他と異なるものが記憶に残りやすくなる現象。周囲との差が、注意と記憶を引きつける。","new_summary":"並んだ項目の中で一つだけ異なるものが、他より記憶されやすい現象。目立たせれば必ず理解が深まるわけではなく、何を区別したいかを絞る必要がある。","old_note":null,"new_note":null},{"id":"kb_211","title":"抑制学習モデル","old_summary":"恐れている状況でも危険が起きない経験を重ね、安全についての新しい学習が恐怖反応を抑えるとするモデル。古い恐怖記憶と新しい学習の関係を扱う。","new_summary":"恐怖記憶を消すのではなく、「恐れても安全である」という新しい記憶を学び、恐怖反応を抑える考え方。","old_note":null,"new_note":null},{"id":"kb_531","title":"ツァイガルニク効果","old_summary":"完了した課題より、中断された課題の方が記憶に残りやすいとされる現象。再現の強さは、課題や中断の条件によって異なる。","new_summary":"完了した課題より、中断された未完了課題の方が記憶や注意に残りやすいとされる現象。未完了が再開の手掛かりになる一方、常に強く再現される単純な法則ではない。","old_note":null,"new_note":null},{"id":"kb_925","title":"接触仮説","old_summary":"対等な立場や共通目標のもとで異なる集団の人が協力すると、偏見が弱まりうるという仮説。接触の質と、それを支える環境が重要になる。","new_summary":"異なる集団の人同士の接触が、偏見を減らしうるという仮説。対等な立場、共通目標、協力、制度の支えなど、接触の質が重要になる。違う世代や文化の人と協働する設計に役立つ。単に同じ場所へ集めればよいわけではなく、敵対的な経験は逆効果にもなりうる。単純接触効果とは対象と説明範囲が異なる。","old_note":null,"new_note":null},{"id":"kb_965","title":"注意資源理論","old_summary":"複数の課題が限られた処理資源を分け合うため、同時に求められる処理量が増えると成績が下がりうるという説明。難しい文章を読みながら込み入った会話をすると、どちらかの内容を落としやすい。","new_summary":"複数の課題が限られた処理資源を分け合うため、同時に求められる処理量が増えると成績が下がりうるという説明。難しい文章を読みながら込み入った会話をすると、どちらかの内容を落としやすい。仕事では同時進行を当然視せず、集中を必要とする時間を分ける設計に役立つ。練習で自動化された処理や、異なる種類の資源を使う課題もあるため、すべての組合せが同じ程度に干渉するとは限らない。","old_note":null,"new_note":null},{"id":"kb_818","title":"心の理論","old_summary":"他者には自分と異なる知識・信念・意図・感情があると理解し、その立場から行動を推測する能力。","new_summary":"他者が自分とは異なる信念、知識、意図、感情を持つと推論する能力概念。推測は事実ではないため、重要場面では確認する。","old_note":null,"new_note":null},{"id":"kb_926","title":"現実的葛藤理論","old_summary":"集団が限られた資源や報酬を奪い合うと、敵意や偏見が強まりうるという理論。協力しなければ達成できない共通目標は、対立の緩和につながる。","new_summary":"集団同士が限られた資源や報酬を競うと、相手集団への敵意や偏見が強まりうるという理論。共同でしか達成できない上位目標は、関係を変える手掛かりになる。職場の対立では性格だけでなく報酬や予算の配分を見る。すべての偏見が資源競争だけで生じるわけではなく、集団の区分だけでも起こる影響と区別する。","old_note":null,"new_note":null},{"id":"kb_967","title":"注意残余","old_summary":"ある仕事から別の仕事へ移っても、直前の仕事への思考が残り、新しい仕事に注意を十分向けにくくなる現象。未完の企画を中断して会議に入ると、会議中も企画の続きが気になることが例になる。","new_summary":"ある仕事から別の仕事へ移っても、直前の仕事への思考が残り、新しい仕事に注意を十分向けにくくなる現象。未完の企画を中断して会議に入ると、会議中も企画の続きが気になることが例になる。切り替え前に次に行うことを短く記録し、区切りを設けるなど、移行を設計する手掛かりになる。単に切り替えに時間がかかる現象や未完了課題の記憶優位とは焦点が異なり、残余の程度は課題や中断条件で変わる。","old_note":null,"new_note":null},{"id":"kb_927","title":"ステレオタイプ内容モデル","old_summary":"人々が集団を、主に温かさと有能さの二軸で評価するというモデル。組み合わせによって、尊敬・羨望・同情・軽蔑など異なる反応が生じる。","new_summary":"集団への固定観念を、主に温かさと有能さの二つの評価軸で捉えるモデル。好意と能力の評価は同じ方向とは限らず、羨望や同情を含む複雑な偏見が生じる。人を「良い・悪い」の一軸で決める前に、何を推測しているかを振り返る。実際の能力や人格を判定する尺度ではなく、評価者側の認知を説明する。","old_note":null,"new_note":null},{"id":"kb_968","title":"注意の捕捉","old_summary":"現在行っている課題とは別の刺激に注意が引き寄せられる現象。読書中に突然の通知音へ目を向けるように、刺激の目立ちやすさや、自分の目標に合う特徴が関わる。","new_summary":"現在行っている課題とは別の刺激に注意が引き寄せられる現象。読書中に突然の通知音へ目を向けるように、刺激の目立ちやすさや、自分の目標に合う特徴が関わる。集中したい場面では不要な通知を減らし、必要な警告は適切に目立たせる設計に使える。ただし目立つ物なら何でも必ず注意を奪うわけではない。注意を向ける準備、課題の負荷、学習した価値によって捕捉されやすさが変わる。","old_note":null,"new_note":null},{"id":"kb_725","title":"統制の所在","old_summary":"自分に起こる結果を、自分の行動で左右できると考えるか、運や他者など外部の力によると考えるかという期待の傾向。","new_summary":"結果を自分の行動に左右されると見るか、運や権力など外部要因に左右されると見るかという一般的期待。内的統制が常に良いわけではなく、制御不能な状況で責任を抱えすぎる危険もある。","old_note":null,"new_note":null},{"id":"kb_970","title":"選択的注意","old_summary":"同時に入る多くの情報のうち、目的に関係する対象を優先して処理する働き。騒がしい場所で相手の話へ注意を向けると、周囲の会話の内容は把握しにくくなる。","new_summary":"同時に入る多くの情報のうち、目的に関係する対象を優先して処理する働き。騒がしい場所で相手の話へ注意を向けると、周囲の会話の内容は把握しにくくなる。会議や学習では注目すべき対象を明確にし、重要な情報が見落とされる可能性も見込んで確認を設ける。選択されなかった情報がすべて処理されないという意味ではない。注意の選択は、刺激、目標、慣れ、負荷に応じて変わる。","old_note":null,"new_note":null},{"id":"kb_993","title":"道徳基盤理論","old_summary":"道徳判断の違いを、ケア、公正、忠誠、権威、神聖など複数の関心の重みから説明する理論。ある提案を一方は公平さ、他方は共同体の秩序から評価すると、同じ結論を求めても対話が噛み合わない場合がある。","new_summary":"道徳判断の違いを、ケア、公正、忠誠、権威、神聖など複数の関心の重みから説明する理論。ある提案を一方は公平さ、他方は共同体の秩序から評価すると、同じ結論を求めても対話が噛み合わない場合がある。反対意見を悪意と決めず、何を守りたいのかを聞く視点になる。基盤の数や測定、文化への一般化には議論があり、人を固定した政治的型へ分ける道具ではない。価値の違いを説明することと、その行為を倫理的に正当化することも別である。","old_note":null,"new_note":null},{"id":"kb_718","title":"真実性錯覚","old_summary":"同じ主張に繰り返し触れると、なじみやすさから真実らしく感じやすくなる現象。繰り返し聞いたという経験が、正しさの判断に混ざる。","new_summary":"同じ主張へ繰り返し触れると、親しみや処理の流暢さから真実らしく感じやすくなる現象。既知の知識があっても起こりうるため、反復回数ではなく根拠を確かめる。","old_note":null,"new_note":null},{"id":"kb_882","title":"テロ管理理論","old_summary":"死を避けられないという不安を、文化的な価値観や自尊心が和らげるとする理論。死を意識したときに、所属や信念を守ろうとする反応を扱う。","new_summary":"人が自分の死の不可避性を意識できることと、その不安を抑える文化的な世界観、自尊心への依存を結びつける理論。価値観や所属集団を守る反応を説明しようとする。死を意識させる操作である死の顕現性は、この理論を検討する個別概念であり、理論全体とは別に扱う。死の意識が全員に同じ反応を起こすという法則ではない。","old_note":null,"new_note":null},{"id":"kb_972","title":"スキーマ理論","old_summary":"経験から作られた知識の枠組みが、新しい情報の理解、記憶、推測を方向づけるという考え方。会議と聞けば議題や発言順を予想できるが、実際にはなかった内容まで補って思い出すこともある。","new_summary":"経験から作られた知識の枠組みが、新しい情報の理解、記憶、推測を方向づけるという考え方。会議と聞けば議題や発言順を予想できるが、実際にはなかった内容まで補って思い出すこともある。学習では既に知る構造に新しい知識を結びつけ、同時にその枠に合わない事実を確かめる視点になる。知識の構造を扱う概念であり、連想の一時的な活性化を説明するプライミングや、信念を守る確証バイアスと同義ではない。","old_note":null,"new_note":null},{"id":"kb_994","title":"道徳的切り離し","old_summary":"通常は働く道徳的な自己抑制を、正当化や責任の分散、被害の軽視などで外してしまう過程。相手を傷つける言動でも「会社のため」「皆がやっている」と説明すると、自分を責めずに続けられる場合がある。","new_summary":"通常は働く道徳的な自己抑制を、正当化や責任の分散、被害の軽視などで外してしまう過程。相手を傷つける言動でも「会社のため」「皆がやっている」と説明すると、自分を責めずに続けられる場合がある。組織や日常の判断では、目的の説明と実際の被害、誰が決めたかを分けて確認する手掛かりになる。本人に罪悪感がないことを、被害がない証拠にしない。違反を必ず生む性格特性や、単なる認知的不協和の別名ではない。","old_note":null,"new_note":null},{"id":"kb_973","title":"スクリプト理論","old_summary":"よく経験する出来事の典型的な順序が、ひとまとまりの知識として理解や記憶を助けるという説明。飲食店で入店、注文、食事、支払いを予測できるのが例になる。","new_summary":"よく経験する出来事の典型的な順序が、ひとまとまりの知識として理解や記憶を助けるという説明。飲食店で入店、注文、食事、支払いを予測できるのが例になる。初めての業務の手順を伝えるときは、相手が前提としている順序を確かめると行き違いを減らせる。実際の出来事が典型と異なると、抜けた工程を勝手に補う場合もある。一般的なスキーマのうち出来事の系列に焦点を当て、台本の読み上げ技法とは区別する。","old_note":null,"new_note":null},{"id":"kb_995","title":"ルーピング効果","old_summary":"人を分類する概念が当事者の自己理解や行動を変え、その変化が分類自体の理解や運用へ戻るという相互作用。ある集団に名称が与えられると、当事者がそれに応答し、分類を研究・管理する側も定義を修正する場合がある。","new_summary":"人を分類する概念が当事者の自己理解や行動を変え、その変化が分類自体の理解や運用へ戻るという相互作用。ある集団に名称が与えられると、当事者がそれに応答し、分類を研究・管理する側も定義を修正する場合がある。診断名や人物像を扱うとき、分類を受ける人の反応まで含めて考える視点になる。期待が現実になる自己成就予言と重なる面はあるが、分類と人が共に変わる過程に焦点がある。あらゆる分類で同じ影響が起きるとは限らない。","old_note":null,"new_note":null},{"id":"kb_974","title":"展望記憶","old_summary":"将来の適切な時点で、予定していた行動を思い出して実行するための記憶。午後3時に連絡する時間ベースの予定と、相手に会ったら資料を渡す出来事ベースの予定などがある。","new_summary":"将来の適切な時点で、予定していた行動を思い出して実行するための記憶。午後3時に連絡する時間ベースの予定と、相手に会ったら資料を渡す出来事ベースの予定などがある。予定を覚えているだけでは足りず、別の活動中に実行のきっかけを検出する必要がある。仕事では通知や物の配置を具体的な行動に結び付けるとよい。過去を思い出す記憶や、将来を想像することとは異なり、失敗を意欲不足だけで説明しない。","old_note":null,"new_note":null},{"id":"kb_996","title":"ラベリング理論","old_summary":"ある行為や人が逸脱と名付けられ、周囲からそう扱われる過程が、その後の立場や自己理解、行動に影響することに注目する社会学の理論。失敗した新人を「問題のある人」と呼び続けると、学ぶ機会や参加が制限される場合などを考えられる。","new_summary":"ある行為や人が逸脱と名付けられ、周囲からそう扱われる過程が、その後の立場や自己理解、行動に影響することに注目する社会学の理論。失敗した新人を「問題のある人」と呼び続けると、学ぶ機会や参加が制限される場合などを考えられる。行為の評価と、人の全体への固定した名付けを分ける視点になる。ラベルだけが逸脱の原因という主張ではなく、実際の行為や環境条件も必要である。感情に名前を付ける感情ラベリングとは別概念。","old_note":null,"new_note":null},{"id":"kb_975","title":"前向干渉・逆向干渉","old_summary":"似た内容の記憶同士が競合し、学習や想起を妨げる現象。古い暗証番号が新しい番号の想起を邪魔するのが前向干渉、新しい番号の学習で古い番号を思い出しにくくなるのが逆向干渉である。","new_summary":"似た内容の記憶同士が競合し、学習や想起を妨げる現象。古い暗証番号が新しい番号の想起を邪魔するのが前向干渉、新しい番号の学習で古い番号を思い出しにくくなるのが逆向干渉である。似た手順を覚える際は、違いを明示し、適切な状況で取り出す練習を設ける。単に時間が経ったための忘却とは区別する。二方向を比較する一つのカードとし、どの記憶が必ず消えるかを予測する法則にはしない。","old_note":null,"new_note":null},{"id":"kb_997","title":"スティグマ","old_summary":"ある属性が社会的に否定的な意味と結び付き、その人全体への評価や扱いを不利にすること。病歴や出自を知っただけで能力まで低く見積もる場合などがある。","new_summary":"ある属性が社会的に否定的な意味と結び付き、その人全体への評価や扱いを不利にすること。病歴や出自を知っただけで能力まで低く見積もる場合などがある。個人の思い込みだけでなく、情報の管理、関係、機会へのアクセスまで含めて理解する。対人場面では必要な情報と偏見を分け、本人の開示の意思を尊重する。属性そのものが本質的に劣っているという意味ではなく、文化や制度、状況によって何が不名誉とされるかは変わる。","old_note":null,"new_note":null},{"id":"kb_976","title":"舌先現象","old_summary":"知っている語や名前を思い出せそうだと感じながら、今はうまく取り出せない状態。人物の職業や名前の頭文字は浮かぶのに、名前全体が出てこないことが例になる。","new_summary":"知っている語や名前を思い出せそうだと感じながら、今はうまく取り出せない状態。人物の職業や名前の頭文字は浮かぶのに、名前全体が出てこないことが例になる。情報が失われた場合と、一時的な検索の失敗を分けて考える手掛かりになる。少し時間を置く、関連する文脈を確かめるなどで思い出すこともあるが、必ず解決する方法ではない。日常で時々起きる現象だけを根拠に、認知機能の病気や知識不足を判断しない。","old_note":null,"new_note":null},{"id":"kb_998","title":"トマスの定理","old_summary":"人々がある状況を現実だと定義すれば、その定義に基づいた行動は現実の結果をもつ、という社会学の命題。実際には起きていない不足の噂でも、人々が買いだめすれば店頭の不足につながる場合がある。","new_summary":"人々がある状況を現実だと定義すれば、その定義に基づいた行動は現実の結果をもつ、という社会学の命題。実際には起きていない不足の噂でも、人々が買いだめすれば店頭の不足につながる場合がある。事実を確かめるだけでなく、どのように状況が理解され、行動が変わるかを見る手掛かりになる。思えば何でも実現するという法則ではなく、誤った認識が常に自らを実現するとも限らない。自己成就予言より広い、状況の定義と結果の関係を扱う。","old_note":null,"new_note":null},{"id":"kb_977","title":"フラッシュバルブ記憶","old_summary":"驚きや重大さを伴う出来事の知らせを受けた状況について、鮮明に覚えていると感じる記憶。大きな出来事をどこで誰から聞いたかが詳しく浮かぶことなどが例になる。","new_summary":"驚きや重大さを伴う出来事の知らせを受けた状況について、鮮明に覚えていると感じる記憶。大きな出来事をどこで誰から聞いたかが詳しく浮かぶことなどが例になる。鮮明さや確信は正確さと同じではなく、後の情報や反復によって内容が変わる場合もある。証言や会話では「はっきり覚えている」という感覚だけで確認を省かず、記録と照らす。写真のような完全保存を意味せず、すべての強い記憶がこの種類になるわけでもない。","old_note":null,"new_note":null},{"id":"kb_999","title":"象徴的相互作用論","old_summary":"人は物事がもつ意味に基づいて行動し、その意味は他者との相互作用や解釈を通して作られ、変わると捉える立場。会議での沈黙が、ある職場では同意、別の職場では慎重な検討と理解されることなどが例になる。","new_summary":"人は物事がもつ意味に基づいて行動し、その意味は他者との相互作用や解釈を通して作られ、変わると捉える立場。会議での沈黙が、ある職場では同意、別の職場では慎重な検討と理解されることなどが例になる。行き違いを考える際、行動だけでなく当事者がそこに与えた意味を確かめる視点になる。すべての意味が自由に選べるわけではなく、制度や力関係の影響もある。個別の心理効果や会話の手順ではなく、社会を理解する理論的視角である。","old_note":null,"new_note":null},{"id":"kb_1000","title":"社会的表象理論","old_summary":"集団の中で共有される知識やイメージが、身近でない事象を理解し、語り、行動する枠組みになると捉える理論。新しい技術が「便利な道具」や「脅威」として日常会話に取り込まれていく過程などを考える。","new_summary":"集団の中で共有される知識やイメージが、身近でない事象を理解し、語り、行動する枠組みになると捉える理論。新しい技術が「便利な道具」や「脅威」として日常会話に取り込まれていく過程などを考える。言葉を伝えるときは、相手の集団でその対象がどう理解されているかを確かめる手掛かりになる。全員が同じ意見をもつという意味ではなく、表象は対話や対立を通して変わる。多数派への同調や単なるステレオタイプとは説明対象が異なる。","old_note":null,"new_note":null},{"id":"kb_978","title":"回想バンプ","old_summary":"中高年以降に人生を振り返った際、青年期から成人初期の出来事が相対的に多く想起される傾向。昔の友人との出会いや進学の記憶が、他の時期より多く浮かぶことなどが例になる。","new_summary":"中高年以降に人生を振り返った際、青年期から成人初期の出来事が相対的に多く想起される傾向。昔の友人との出会いや進学の記憶が、他の時期より多く浮かぶことなどが例になる。人生の語りや世代間の対話では、思い出されやすさと当時の出来事の客観的重要性を分けて考えられる。山が現れる年齢や大きさは、質問、手掛かり、文化などで変わる。人生の最良期が若い時期に固定されるという主張ではない。","old_note":null,"new_note":null},{"id":"kb_1001","title":"道徳的パニック","old_summary":"ある人々や出来事が社会の価値を脅かすものとして描かれ、報道や社会的反応によって懸念や統制要求が急激に高まる過程を捉える社会学的概念。少数の事例から特定集団全体が危険だと語られる場合などを分析できる。","new_summary":"ある人々や出来事が社会の価値を脅かすものとして描かれ、報道や社会的反応によって懸念や統制要求が急激に高まる過程を捉える社会学的概念。少数の事例から特定集団全体が危険だと語られる場合などを分析できる。情報を読む際は、実際の発生頻度、被害、報道の規模を別々に確認する。懸念の存在だけで「パニック」と決めつけず、反応が不釣り合いかを資料で検討する必要がある。実在する被害を否定するための言葉ではない。","old_note":null,"new_note":null},{"id":"kb_706","title":"ダニング＝クルーガー効果","old_summary":"課題の成績が低い人の自己評価ほど、実際の成績を上回りやすいという研究知見。誤りに気づく力に加え、課題や測定方法も自己評価のずれに関わる。","new_summary":"技能が低い人ほど自分の誤りを見抜くための技能も不足し、自己評価を誤りやすいという研究知見。誰もが無知なら自信過剰になるという単純な序列ではなく、課題・測定法・統計的回帰の影響も議論されている。","old_note":null,"new_note":null},{"id":"kb_979","title":"偽記憶","old_summary":"実際には起きなかった出来事を覚えていると感じたり、起きた出来事を実際と異なる形で思い出したりすること。会話で聞いた内容を、自分が直接見たこととして思い出す場合などがある。","new_summary":"実際には起きなかった出来事を覚えていると感じたり、起きた出来事を実際と異なる形で思い出したりすること。会話で聞いた内容を、自分が直接見たこととして思い出す場合などがある。記憶は再構成されるため、誤情報、連想、出所の取り違えなど複数の経路が関わる。聞き取りでは誘導的な質問を避け、独立した記録を照合する。記憶違いと意図的な嘘は別であり、この概念だけで個別の記憶が真か偽かを決められない。","old_note":null,"new_note":null},{"id":"kb_1002","title":"他者化","old_summary":"ある人々を「私たち」とは本質的に異なる存在として描き、所属や権利、共感の範囲から外す過程。所属部署や出自の違いから「彼らは分かり合えない」と一括りにすると、個々の事情を聞く機会が失われる。","new_summary":"ある人々を「私たち」とは本質的に異なる存在として描き、所属や権利、共感の範囲から外す過程。所属部署や出自の違いから「彼らは分かり合えない」と一括りにすると、個々の事情を聞く機会が失われる。対話では集団名による説明と、実際の行為や必要を分けて確かめる視点になる。単に違いを認めることや個人的に距離を置くことのすべてを指すわけではない。制度、権力、資源配分も含む概念であり、個人の好悪だけでは説明できない。","old_note":null,"new_note":null},{"id":"kb_901","title":"認知行動療法","old_summary":"思考・感情・身体反応・行動のつながりを整理し、認知と行動の両面から困難への対処を学ぶ心理療法の総称。目的に応じて行動実験や認知の検討などを用いる。","new_summary":"思考、感情、身体反応、行動の関係を整理し、認知と行動の両面から困難への対応を検討する心理療法の総称。考えを吟味する方法や行動実験などを、目的に応じて組み合わせる。単に前向きな考えへ置き換える方法ではない。曝露や行動活性化などの個別技法と区別し、対象とする問題に応じた評価や専門的な支援のもとで用いる。","old_note":null,"new_note":null},{"id":"kb_980","title":"プルースト効果","old_summary":"においが、個人的な過去の出来事と当時の感情を呼び起こす現象を指す通称。昔使った石けんの香りから、家族との生活場面が急に浮かぶような例で理解できる。","new_summary":"においが、個人的な過去の出来事と当時の感情を呼び起こす現象を指す通称。昔使った石けんの香りから、家族との生活場面が急に浮かぶような例で理解できる。においと言葉や写真では、想起される記憶の感情的性質が異なる場合がある。思い出を語るきっかけにはなるが、香りが誰にでも良い記憶を作る、記憶を正確に復元するという効果ではない。不快な経験を思い出す人もいるため、利用時は本人の反応を優先する。","old_note":null,"new_note":null},{"id":"kb_1003","title":"共有現実理論","old_summary":"ある対象について、自分と他者の内的な理解や感情が共通していると感じる経験に注目する理論。出来事を話し「同じように見ていた」と感じることで、自分の解釈への確信が支えられる場合などがある。","new_summary":"ある対象について、自分と他者の内的な理解や感情が共通していると感じる経験に注目する理論。出来事を話し「同じように見ていた」と感じることで、自分の解釈への確信が支えられる場合などがある。対話では結論だけでなく、どの意味や感情を共有したのかを確かめる視点になる。表面的に同じ発言をしただけでは共有現実とは限らず、共感や共通知識とも区別される。共有によって判断が正確になる保証はなく、偏った理解が強まる場合も考慮する。","old_note":null,"new_note":null},{"id":"kb_1004","title":"相互独立的・相互協調的自己観","old_summary":"自己を他者から区切られた独立した存在として捉える見方と、関係や役割の中で捉える見方を比較する枠組み。意思表示を「自分の希望を伝えること」と捉えるか、「関係の調整」と捉えるかで、同じ言動の意味が変わる場合がある。","new_summary":"自己を他者から区切られた独立した存在として捉える見方と、関係や役割の中で捉える見方を比較する枠組み。意思表示を「自分の希望を伝えること」と捉えるか、「関係の調整」と捉えるかで、同じ言動の意味が変わる場合がある。文化や職場の違いを理解するとき、自分の当然を点検する手掛かりになる。国籍で人を二分したり、一方が成熟していると評価したりしない。同じ人でも関係や場面によって、両方の見方を使いうる。","old_note":null,"new_note":null},{"id":"kb_439","title":"信頼の段階的回復","old_summary":"小さな約束を守る経験を積み重ね、損なわれた信頼を少しずつ取り戻す過程。許すこと、交流を再開すること、任せる範囲を広げることには異なる段階がある。","new_summary":"損なわれた信頼は、謝罪一回で元に戻るのではなく、小さな約束を守る経験を積み重ねて再構築される。許し、接触再開、権限回復は別々の段階として扱える。","old_note":null,"new_note":null},{"id":"kb_1005","title":"自己評価維持モデル","old_summary":"身近な人の優れた成果が自分の評価に及ぼす影響を、心理的な近さ、成績の差、その領域の自己にとっての重要性から説明するモデル。親友の得意分野を誇らしく感じても、自分の大切な仕事で追い抜かれると脅威を感じることがある。","new_summary":"身近な人の優れた成果が自分の評価に及ぼす影響を、心理的な近さ、成績の差、その領域の自己にとっての重要性から説明するモデル。親友の得意分野を誇らしく感じても、自分の大切な仕事で追い抜かれると脅威を感じることがある。嫉妬や応援が入り交じるとき、相手への好悪だけでなく比較の領域を見直す手掛かりになる。近い人の成功を必ず妬むという法則ではない。関係や自己評価を調整する方法には個人差や状況差がある。","old_note":null,"new_note":null},{"id":"kb_1006","title":"社会的役割理論","old_summary":"性別などによる行動の違いや類似を、社会で担う役割と、その役割への期待から説明する理論。特定の人々がケアや指揮を多く担当すると、その行動が生来の性質だと見られ、役割分担が再生産される場合がある。","new_summary":"性別などによる行動の違いや類似を、社会で担う役割と、その役割への期待から説明する理論。特定の人々がケアや指揮を多く担当すると、その行動が生来の性質だと見られ、役割分担が再生産される場合がある。人材配置では、観察された行動と与えられてきた機会を分けて考える。すべての差を役割だけに還元するものではなく、生物的条件と社会構造の関係も検討する。既存の役割に従うべきだという規範ではない。","old_note":null,"new_note":null},{"id":"kb_990","title":"自尊心の随伴性","old_summary":"自分の価値が、他者の承認、競争での成功、外見など特定の領域の結果にどれほど依存しているかを捉える枠組み。仕事の失敗を能力の一部への評価でなく「自分には価値がない」と受け止める場合などが例になる。","new_summary":"自分の価値が、他者の承認、競争での成功、外見など特定の領域の結果にどれほど依存しているかを捉える枠組み。仕事の失敗を能力の一部への評価でなく「自分には価値がない」と受け止める場合などが例になる。自尊心の高低だけでなく、何に支えられ、どんな出来事で揺れるかを見直す手掛かりになる。達成に価値を置くこと自体が必ず有害なわけではない。依存する領域や、その領域での経験によって影響は変わる。","old_note":null,"new_note":null},{"id":"kb_397","title":"脆弱性の相互性","old_summary":"自分の不安や弱さを適度に打ち明けると、相手も自分を開示しやすくなり、相互理解が深まることがあるという考え。","new_summary":"一方が不安や弱さを適度に開示すると、相手も自己開示しやすくなり、相互理解が深まることがある。ただし負担の大きい開示や、一方的な感情処理の依頼まで正当化する概念ではない。","old_note":null,"new_note":null},{"id":"kb_991","title":"多次元的完璧主義","old_summary":"完璧さへの要求を一種類とせず、自分への要求、他者への要求、他者から要求されている感覚などに分けて捉える枠組み。資料を何度も直す人でも、自分の基準の高さと「少しでも誤ると見放される」という受け止めでは対応が違う。","new_summary":"完璧さへの要求を一種類とせず、自分への要求、他者への要求、他者から要求されている感覚などに分けて捉える枠組み。資料を何度も直す人でも、自分の基準の高さと「少しでも誤ると見放される」という受け止めでは対応が違う。基準、失敗への反応、対人期待を分けて振り返るために使える。異なる研究者の尺度には別の次元構成もあり、単一の分類で人を断定しない。丁寧さや高い目標がすべて問題だという意味ではない。","old_note":null,"new_note":null},{"id":"kb_566","title":"相対的剥奪","old_summary":"自分が得るべきだと感じる水準や比較相手との差によって、不満や不公平感が生まれること。同じ境遇でも、誰と比べるかで受け止めが変わる。","new_summary":"客観的な生活水準ではなく、自分が当然得られると思う基準や比較相手との差から、不満や不公平感が生じること。比較集団が変わると同じ状況の評価も変わる。","old_note":null,"new_note":null},{"id":"kb_992","title":"達成動機理論","old_summary":"優れた基準に照らして成功したい動機と、失敗を避けたい動機が、挑戦や課題選択にどう関わるかを説明する理論群。成功を試したい人が適度に難しい課題を選ぶ一方、失敗を強く恐れる人が極端に容易な課題へ寄る場合などを考える。","new_summary":"優れた基準に照らして成功したい動機と、失敗を避けたい動機が、挑戦や課題選択にどう関わるかを説明する理論群。成功を試したい人が適度に難しい課題を選ぶ一方、失敗を強く恐れる人が極端に容易な課題へ寄る場合などを考える。目標設定では、難度だけでなく成功の見込みや失敗の意味づけを確かめる。すべての行動を競争心で説明するものではなく、動機、状況、文化、使うモデルによって予測は異なる。","old_note":null,"new_note":null},{"id":"kb_006","title":"相補性","old_summary":"異なる性質や役割が補い合うことで、関係が安定したり成果が高まったりすること。互いの違いが、関係の中で役立つ場合を捉える。","new_summary":"互いに異なる性質や役割が補い合うことで、関係が安定したり成果が高まったりする考え方。似ていることだけが相性を決めるわけではない。","old_note":null,"new_note":null},{"id":"kb_224","title":"脱中心化","old_summary":"浮かんだ思考や感情を、一時的な心の出来事として観察する視点。気持ちに巻き込まれることを弱め、反応を選ぶ余地をつくる。","new_summary":"自分の思考や感情を、自分そのものではなく一時的な心の出来事として観察する視点。","old_note":null,"new_note":null},{"id":"kb_223","title":"認知的脱フュージョン","old_summary":"頭に浮かんだ言葉やイメージと距離を取り、その思考へのとらわれを弱める方法。思考に従うかどうかを選びやすくする。","new_summary":"思考を事実や命令としてではなく、頭に浮かんだ言葉やイメージとして距離を置いて捉える方法。","old_note":null,"new_note":null},{"id":"kb_578","title":"筆記開示","old_summary":"感情を伴う経験について、出来事と気持ちを文章にして整理する方法。経験の意味づけや感情の理解を助ける可能性があり、効果は人や状況によって異なる。","new_summary":"感情的な出来事について、事実と感情を一定時間文章にして表現する方法。経験の整理や意味づけを助ける可能性があるが、効果には個人差があり治療の代替ではない。","old_note":null,"new_note":null},{"id":"kb_202","title":"行動活性化","old_summary":"生活の中で価値や達成感につながる活動を計画し、抑うつや回避の悪循環を変えていく心理的介入。取り組める小さな行動から始める。","new_summary":"気分の改善を待つのではなく、価値ある活動を先に増やすことで抑うつや回避を減らす心理的介入。","old_note":null,"new_note":null},{"id":"kb_986","title":"感情調整プロセスモデル","old_summary":"感情が生じて表れるまでの過程に沿って、状況選択、状況修正、注意の配分、認知の変化、反応の調整を区別するモデル。苦手な会議では、準備や席の選び方を変えることと、会議中に表情を抑えることは介入する段階が違う。","new_summary":"感情が生じて表れるまでの過程に沿って、状況選択、状況修正、注意の配分、認知の変化、反応の調整を区別するモデル。苦手な会議では、準備や席の選び方を変えることと、会議中に表情を抑えることは介入する段階が違う。感情を我慢する以外の選択肢を探すために使える。ただし各方略が常に良い・悪いわけではなく、目的や対人状況に応じて機能が変わる。感情を完全に消す方法を示すものではない。","old_note":null,"new_note":null},{"id":"kb_987","title":"情動粒度","old_summary":"焦り・落胆・怒りなど、自分の感情を細かく区別して捉えられる程度。同じ「つらい」でも、どの感情かを知ることで必要な対応が見えやすくなる。","new_summary":"自分の感情経験を、単に良い・悪いだけでなく、焦り、落胆、怒りなどとして細かく区別する程度。仕事で同じ「つらい」でも、期限への焦りか、扱われ方への怒りかで必要な対応は違う。感情を記録するとき、状況に合う言葉を探すための視点になる。研究では日々の報告のパターンなどから測り、語彙の多さだけと同一視しない。精神的健康との関連はあるが、言葉を増やせば必ず症状が改善するという因果の保証ではない。","old_note":null,"new_note":null},{"id":"kb_988","title":"感情構成理論","old_summary":"感情を、身体内部の感覚、過去の経験、概念、状況に基づいて脳が構成する経験として捉える理論。同じ動悸でも、発表前には不安、競技前には高揚として経験することを考える枠組みになる。","new_summary":"感情を、身体内部の感覚、過去の経験、概念、状況に基づいて脳が構成する経験として捉える理論。同じ動悸でも、発表前には不安、競技前には高揚として経験することを考える枠組みになる。自分の感情の意味を考える際、身体と文脈の両方に目を向けられる。ただし感情が好きに選べる、身体反応が存在しないという意味ではない。基本情動説などと議論が続く理論であり、すべての感情研究が合意した最終説明ではない。","old_note":null,"new_note":null},{"id":"kb_989","title":"社会的評価不安","old_summary":"他者からどう評価されるかへの心配や、否定的に見られることへの不安。発表で内容より失敗の印象ばかり気になり、質問を避けることなどが例になる。","new_summary":"他者からどう評価されるかへの心配や、否定的に見られることへの不安。発表で内容より失敗の印象ばかり気になり、質問を避けることなどが例になる。行動を振り返るとき、実際の評価、予測した評価、その予測から取った回避行動を分けて整理できる。社会的状況の不快感や否定的評価への恐れを測る研究があるが、これだけで病気を診断する概念ではない。程度や生活上の影響は人によって異なり、現実の不公正な評価環境も見落とさない。","old_note":null,"new_note":null},{"id":"kb_419","title":"ミケランジェロ現象","old_summary":"親しい相手が本人の理想の自己を理解し、それに沿う行動を支えることで、その人が望む自分へ近づきやすくなる現象。","new_summary":"親しい相手が本人の理想自己を理解し、それに沿う行動を肯定・支援することで、本人が理想の自己へ近づきやすくなる現象。相手を自分の理想どおりに作り変えることではない。","old_note":null,"new_note":null},{"id":"kb_957","title":"サブリミナル効果","old_summary":"意識的には識別できないほど短時間・低強度の刺激が、条件によって後続の知覚や反応に影響する現象。閾下での処理と、意識できる刺激によるプライミングを区別する。","new_summary":"意識的には識別できないほど短時間・低強度の刺激が、条件によって後続の知覚や反応に影響する現象。閾下での処理と、意識できる刺激によるプライミングを区別する。実験では刺激の見え方を測定し、反応の小さな差を調べる。隠した広告で誰の意思でも長期間支配できるという意味ではない。広告の効果を考える際は、閾値の測定、実験条件、実生活での再現性まで確認する。","old_note":null,"new_note":null},{"id":"kb_958","title":"信号検出理論","old_summary":"雑音の中で信号を見分ける判断を、感度と判定基準に分けて説明する理論。命中、見逃し、誤警報、正しい棄却を区別し、見逃しを減らす設定が誤警報を増やす場合も評価する。","new_summary":"雑音の中で信号を見分ける判断を、感度と判定基準に分けて説明する理論。命中、見逃し、誤警報、正しい棄却を区別し、見逃しを減らす設定が誤警報を増やす場合も評価する。例えば検品で不良品を多く発見しても、正常品まで大量に除いていれば感度が高いとは限らない。注意力の良し悪しを一つの正答率だけで決めないために使える。成績は信号の出現率や損失の見積もりにも左右される。","old_note":null,"new_note":null},{"id":"kb_959","title":"ウェーバーの法則","old_summary":"刺激の違いに気づくために必要な変化量は、一定範囲では元の刺激強度に比例するという精神物理学の法則。軽い荷物には小さな増量でも気づくが、重い荷物では同じ増量が分かりにくい。","new_summary":"刺激の違いに気づくために必要な変化量は、一定範囲では元の刺激強度に比例するという精神物理学の法則。軽い荷物には小さな増量でも気づくが、重い荷物では同じ増量が分かりにくい。弁別閾を絶対量だけでなく比率で考える手掛かりになる。値上げや音量調節の理解にも参考になるが、感覚の種類や強度の端では単純な比例が崩れる。価格への態度や満足のすべてを説明する経済法則ではない。","old_note":null,"new_note":null},{"id":"kb_960","title":"感覚順応","old_summary":"同じ刺激が続くと、その刺激に対する感覚系の反応や主観的な強さが変わる現象。部屋のにおいを入室直後ほど感じなくなることなどが例になる。","new_summary":"同じ刺激が続くと、その刺激に対する感覚系の反応や主観的な強さが変わる現象。部屋のにおいを入室直後ほど感じなくなることなどが例になる。変化を検出しやすくする働きがある一方、慣れた環境では刺激の存在を過小評価する可能性もある。環境確認では自分の感覚だけに頼らず、必要なら測定器や別の人の確認を使う。報酬による学習、注意の慣れ、幸福感の快楽順応とは説明の水準が異なる。","old_note":null,"new_note":null},{"id":"kb_961","title":"知覚的構え","old_summary":"期待や経験、現在の目的によって、ある解釈や特徴を知覚しやすくなる準備状態。誤植を含む文章でも文脈に沿った語として読める一方、探している物の形にこだわって目の前の別の形を見落とすことがある。","new_summary":"期待や経験、現在の目的によって、ある解釈や特徴を知覚しやすくなる準備状態。誤植を含む文章でも文脈に沿った語として読める一方、探している物の形にこだわって目の前の別の形を見落とすことがある。検品や情報確認では、期待する答えを先に決めず、異なる見方で再確認するとよい。ただし期待が常に知覚を支配するわけではない。信念に合う証拠を集める確証バイアスより、知覚の解釈に焦点を当てる。","old_note":null,"new_note":null},{"id":"kb_962","title":"ゲシュタルトの群化原理","old_summary":"近接、類同、よい連続、閉合などの手掛かりにより、個々の要素をまとまりとして知覚する原理群。資料で近い位置にある項目は同じグループに、形の似た記号は同じ種類に見えやすい。","new_summary":"近接、類同、よい連続、閉合などの手掛かりにより、個々の要素をまとまりとして知覚する原理群。資料で近い位置にある項目は同じグループに、形の似た記号は同じ種類に見えやすい。図解や画面を作る際は、意味のまとまりと視覚的なまとまりを揃えるために使える。複数の原理が競合することもあり、これだけで最適なデザインが決まるわけではない。全体を重視する一般的な人生訓とは区別する。","old_note":null,"new_note":null},{"id":"kb_963","title":"トップダウン処理・ボトムアップ処理","old_summary":"知覚を、既有知識や期待から解釈するトップダウンの方向と、入力された特徴から組み立てるボトムアップの方向で捉える枠組み。読みにくい文字を文脈から補うときと、未知の記号を線や形から見分けるときを比較できる。","new_summary":"知覚を、既有知識や期待から解釈するトップダウンの方向と、入力された特徴から組み立てるボトムアップの方向で捉える枠組み。読みにくい文字を文脈から補うときと、未知の記号を線や形から見分けるときを比較できる。観察では先入観を点検しつつ、経験が理解を助ける面も活かす。実際の知覚は両方向が関わり、どちらかだけが正しいわけではない。経営のトップダウン・ボトムアップ方式を指す用語とは異なる。","old_note":null,"new_note":null},{"id":"kb_460","title":"個人化","old_summary":"相手の経験や特徴に目を向け、一人の固有な人物として理解すること。個別の情報が増えると、集団への固定観念に頼る判断が弱まりやすい。","new_summary":"相手を所属集団の典型としてではなく、固有の経験や特徴を持つ一人として認識すること。個別情報が増えると、ステレオタイプだけに基づく判断が弱まりやすい。","old_note":null,"new_note":null},{"id":"kb_964","title":"予測符号化理論","old_summary":"脳が感覚情報を予測し、実際の入力との差を使って内部の見込みを更新するという説明枠組み。曖昧な図の見え方が文脈によって変わることも、予測と修正の過程から捉える。","new_summary":"上位の処理が下位の入力を予測し、予測と実際の入力の差を使って内部モデルを更新するという説明枠組み。曖昧な図が文脈によって違って見えることを、単なる受動的な受信ではなく予測と修正の過程として考える。思い込みを点検するときは、予測に合わなかった情報にも注意を向ける手掛かりになる。ただし日常の助言は枠組みからの応用例で、脳の全機能が単一の予測算法で説明済みという意味ではない。","old_note":null,"new_note":null},{"id":"kb_966","title":"アフォーダンス","old_summary":"環境が、ある身体や能力をもつ行為者に対して提供する行為の可能性。腰掛けられる高さの段差は大人には座る可能性を与えても、小さな子には同じ使い方を提供しない場合がある。","new_summary":"環境が、ある身体や能力をもつ行為者に対して提供する行為の可能性。腰掛けられる高さの段差は大人には座る可能性を与えても、小さな子には同じ使い方を提供しない場合がある。道具や場所を考える際、物の形だけでなく使う人との関係を見る視点になる。「押す」と書いた表示は行為を伝える手掛かりであり、可能性そのものとは区別する。望ましい行動を必ず起こさせる力や、見た目の分かりやすさだけを指す語ではない。","old_note":null,"new_note":null},{"id":"kb_403","title":"ロジャーズの受容","old_summary":"相手の経験や感情を、その人にとって意味のあるものとして尊重する態度。評価や矯正を急がずに受け止めることが、自己理解と対話を支える。","new_summary":"相手の経験や感情を、直ちに評価・矯正せず、その人にとっての現実として尊重する態度。行為への全面的賛成ではなく、相手を条件付きで価値づけないことを意味する。","old_note":null,"new_note":null},{"id":"kb_969","title":"絶対閾","old_summary":"音や光などの刺激の存在を、一定の確率で感じ取れる最小の強さ。通常は、同じ条件の試行の半数で検出できる強さを基準にする。","new_summary":"統制した測定条件で、刺激の存在を一定の割合、通常は半数の試行で検出できる最小の強度。音量を少しずつ変えて聞こえたかを繰り返し尋ねると、毎回必ず聞こえる境界ではなく検出確率として捉えられる。表示や警告の設計では、測定条件と利用者の違いを確認するために役立つ。疲労、雑音、期待でも結果は変わる。二つの刺激の違いを検出する弁別閾とは別で、全員共通の固定値ではない。","old_note":null,"new_note":null},{"id":"kb_412","title":"アクティブリスニング","old_summary":"相づち・要約・質問・感情の言語化などによって、相手の話を注意深く理解しようとする聴き方。理解のずれを確かめながら対話を進める。","new_summary":"相づち、要約、質問、感情の反映などを用い、注意深く聴いていることを行動で示す技法。受け身に黙るのではなく、理解のずれを確かめながら共同で意味をつくる。","old_note":null,"new_note":null},{"id":"kb_971","title":"心的回転","old_summary":"物体や図形の向きを頭の中で変え、同じ形かどうかを判断する心的操作。異なる角度から描かれた立体を比較する実験では、角度差が大きいほど判断時間が長くなる傾向が示された。","new_summary":"物体や図形の向きを頭の中で変え、同じ形かどうかを判断する心的操作。異なる角度から描かれた立体を比較する実験では、角度差が大きいほど判断時間が長くなる傾向が示された。家具の配置や図面の理解で、向きを変えた姿を想像することが身近な例になる。空間課題を考える基礎概念だが、成績は経験、方略、課題の形式で変わる。空間能力や知能全体を一つの課題で決めつける指標ではない。","old_note":null,"new_note":null},{"id":"kb_981","title":"二重過程理論","old_summary":"推論や判断を、自律的で素早い処理と、作業記憶を使う検討的な処理の違いから説明する理論群。見慣れた答えを即座に選ぶときと、その答えを計算や規則で点検するときを比較できる。","new_summary":"推論や判断を、自律的で素早い処理と、作業記憶を使う検討的な処理の違いから説明する理論群。見慣れた答えを即座に選ぶときと、その答えを計算や規則で点検するときを比較できる。重要な判断では直感の根拠を確認する時間を設ける手掛かりになる。脳に二つの独立した箱があるという主張ではなく、速さだけで処理を判別できるわけでもない。直感が常に誤りで、熟考が常に正しいという意味でもない。","old_note":null,"new_note":null},{"id":"kb_982","title":"属性置換","old_summary":"難しい問いを判断するとき、答えやすい別の属性で知らずに置き換えて答えること。「この計画は成功するか」を「担当者は好ましいか」で判断する場合などがある。","new_summary":"難しい問いを判断するとき、答えやすい別の属性で知らずに置き換えて答えること。「この計画は成功するか」を「担当者は好ましいか」で判断する場合などがある。利用可能な情報が、本来求められた評価を代用してしまう仕組みとして考える。判断を点検するときは、今評価している属性と、本来の問いを別々に書き出す。すべての簡便な判断が属性置換とは限らず、適切な代替指標が役立つ場合もある。好感そのものや確証バイアスと同義ではない。","old_note":null,"new_note":null},{"id":"kb_983","title":"信念バイアス","old_summary":"結論がもっともらしいかどうかによって、論証の論理的な妥当性の判断が影響される傾向。日常的に正しそうな結論だと、前提からその結論が導けていなくても受け入れやすくなる。","new_summary":"結論がもっともらしいかどうかによって、論証の論理的な妥当性の判断が影響される傾向。日常的に正しそうな結論だと、前提からその結論が導けていなくても受け入れやすくなる。議論を読む際は、結論への賛否と、前提を仮に認めたとき推論が成立するかを分けて確かめる。信念に合う情報を探す確証バイアスより、提示済みの推論の評価に焦点を当てる。内容への知識が常に無益という意味ではなく、形式と事実確認の両方が必要である。","old_note":null,"new_note":null},{"id":"kb_984","title":"認知欲求","old_summary":"努力を要する思考に取り組み、それを楽しむ傾向の個人差。複雑な問題の理由を調べることを好む人と、要点だけを早く知りたい人の違いなどに現れる。","new_summary":"努力を要する思考に取り組み、それを楽しむ傾向の個人差。複雑な問題の理由を調べることを好む人と、要点だけを早く知りたい人の違いなどに現れる。説明を作る際は、根拠や比較を求める相手に詳細を用意するなど、関心に応じた伝え方を考えられる。ただし知能や知識量そのものを測る概念ではなく、疲労や関心によっても取り組み方は変わる。結論を早く確定したい認知的閉鎖欲求とは異なる。","old_note":null,"new_note":null},{"id":"kb_985","title":"イデオモーター効果","old_summary":"動作についての考えや期待が、意図していると自覚しにくい小さな運動に結び付く現象。手に持った振り子が、予想した方向へわずかに動くことなどが例になる。","new_summary":"動作についての考えや期待が、意図していると自覚しにくい小さな運動に結び付く現象。手に持った振り子が、予想した方向へわずかに動くことなどが例になる。本人が動かした感覚を持たないことは、外部の不思議な力が働いた証拠にはならない。体験を検討する際は、期待や微細な身体運動を分けて確かめる。行動の模倣や広い社会的プライミングと同義ではなく、あらゆる考えがそのまま実行されるという主張でもない。","old_note":null,"new_note":null},{"id":"kb_427","title":"境界設定","old_summary":"引き受ける責任、使える時間、受け入れられる扱いの範囲を決め、相手に伝えること。自分がどう行動するかを明確にする。","new_summary":"自分が引き受ける責任、使える時間、許容する扱いの範囲を明確にし、相手へ伝えること。相手を支配する規則ではなく、自分が何をするか・しないかを定める。","old_note":null,"new_note":null},{"id":"kb_871","title":"マガーク効果","old_summary":"聞こえる音声と見える口の動きが食い違うと、音声だけを聞いたときとは異なる音節に聞こえることがある現象。発話の知覚で視覚と聴覚が統合されることを示す。","new_summary":"音声と、それとは異なる発音をする口の動きを同時に示すと、音声だけとは違う音節として聞こえることがある現象。発話の知覚には聴覚だけでなく視覚情報も関わる。映像と音声の同期や字幕・口元の見え方を点検する理由になるが、視覚が常に聴覚に勝つわけではなく、刺激や個人によって起こり方が異なる。","old_note":null,"new_note":null},{"id":"kb_784","title":"精緻化可能性モデル","old_summary":"説得の受け止め方を、論拠を吟味する中心ルートと、好感や専門性などの手掛かりを使う周辺ルートから説明するモデル。関心と考える余力が処理の深さを左右する。","new_summary":"説得を、論拠を吟味する中心ルートと、専門性や好感など手がかりを使う周辺ルートで説明するモデル。関与と処理能力が高いほど中心ルートが働きやすいが、二つは完全な二分法ではない。","old_note":null,"new_note":null},{"id":"kb_786","title":"接種理論","old_summary":"弱い反論とそれへの応答をあらかじめ知ることで、後の説得や誤情報に抵抗しやすくなるという理論。想定される主張を検討する経験が判断を支える。","new_summary":"弱い反論とその反駁を先に経験すると、後の強い説得や誤情報への抵抗が高まりうる理論。相手を煽るのではなく、想定反論と検証方法を事前に学ぶ使い方が中心となる。","old_note":null,"new_note":null},{"id":"kb_861","title":"二段階流れ仮説","old_summary":"メディアの情報が、身近なオピニオンリーダーによる解釈や紹介を経て人々へ広がるとする仮説。人間関係が情報の影響を仲介する。","new_summary":"マスメディアの情報が直接一様に届くのではなく、オピニオンリーダーを介して解釈・拡散されるというモデル。","old_note":null,"new_note":null},{"id":"kb_389","title":"メラビアンの法則","old_summary":"好意や反感を伝える言葉と声・表情が食い違うと、受け手は声や表情を重視して相手の気持ちを判断しやすい、という研究知見。","new_summary":"感情や態度を伝える言葉と声・表情が食い違う場面では、受け手が声や表情を強く手掛かりにするという限定的な研究知見。あらゆる会話で「言葉は7％しか伝わらない」という法則ではない。","old_note":null,"new_note":null},{"id":"kb_924","title":"成人愛着スタイル","old_summary":"親密な関係で安心を感じる程度や、見捨てられる不安、近づくことへの回避を捉える枠組み。人との距離や支えを求める行動に関わる。","new_summary":"親密な相手への安心感、見捨てられる不安、近づくことへの回避などの傾向を捉える枠組み。連絡頻度や距離の希望が違うとき、相手の悪意だけでなく関係で感じる不安を考えられる。乳幼児の愛着理論を成人の恋愛へ展開した研究に由来するが、自己診断で固定した性格や関係の運命を決めるものではない。","old_note":null,"new_note":null},{"id":"kb_928","title":"共感的正確性","old_summary":"相手が実際に考えたり感じたりしている内容を、どれほど正確に推測できるかという概念。自分の推測と本人の経験が合っているかに着目する。","new_summary":"相手が実際に考えたり感じたりしていることを、どれほど正確に推測できるかという概念。優しく接することや自分も同じ感情になることとは区別される。理解したつもりのときほど、推測を仮のものとして本人に確かめる。非言語的な手掛かりも使えるが、表情だけで内面を断定できるわけではない。","old_note":null,"new_note":null},{"id":"kb_1007","title":"対人距離理論","old_summary":"対人場面で空間や距離がどう使われ、関係や文化と結び付くかを考える枠組み。初対面で近づきすぎると落ち着かない人がいる一方、同じ距離でも親密さや状況により受け止めは変わる。","new_summary":"対人場面で空間や距離がどう使われ、関係や文化と結び付くかを考える枠組み。初対面で近づきすぎると落ち着かない人がいる一方、同じ距離でも親密さや状況により受け止めは変わる。会話や席の配置では、相手の反応と場所の制約を確かめ、距離を調整する手掛かりになる。親密・個体・社会・公衆距離という整理は、全文化や全員に共通する厳密な物差しではない。距離だけから好意や性格を読み取らない。","old_note":null,"new_note":null},{"id":"kb_1008","title":"ジョハリの窓","old_summary":"自分が知っているか、他者が知っているかの二軸で、自己理解を開放・盲点・秘密・未知の四領域に整理するモデル。自分では普通だと思う振る舞いを同僚から指摘されると、盲点を知る機会になる。","new_summary":"自分が知っているか、他者が知っているかの二軸で、自己理解を開放・盲点・秘密・未知の四領域に整理するモデル。自分では普通だと思う振る舞いを同僚から指摘されると、盲点を知る機会になる。振り返りでは具体的なフィードバックを求め、必要に応じて自己開示するために使える。すべてを開示するほど良いわけではなく、秘密や境界を守ることも大切である。四領域を精密に測定する診断法や、他人の内面を透視する方法ではない。","old_note":null,"new_note":null},{"id":"kb_515","title":"比較優位","old_summary":"他の活動に使えた資源や利益を考慮したとき、相対的に低い費用で行える分野に強みがあること。得意分野を分担し交換することで、双方に利益が生まれる。","new_summary":"すべてで最も優れていなくても、他の選択肢と比べて機会費用が低い活動に集中すれば、交換や分業から利益を得られるという原理。得意の絶対順位ではなく相対差を見る。","old_note":null,"new_note":null},{"id":"kb_555","title":"リスク・オブ・ルイン","old_summary":"一度の損失や損失の積み重ねによって、資金などの基盤を失い、活動を続けられなくなる危険。回復不能な水準へ達する可能性に着目する。","new_summary":"損失が一時的な不調ではなく、資金・健康・信用などを回復不能な水準まで壊す危険。期待値が高い選択でも、破滅確率があるなら賭け金を制限する必要がある。","old_note":null,"new_note":null},{"id":"kb_908","title":"SWOT分析","old_summary":"内部の強み・弱みと、外部の機会・脅威を整理し、その組み合わせから戦略を考える枠組み。対象とする事業や期間を明確にして使う。","new_summary":"内部の強みと弱み、外部の機会と脅威を整理し、戦略を検討する分析枠組み。四つの欄を埋めること自体ではなく、根拠を確認し、それらの組み合わせから優先する行動を選ぶことが目的になる。同じ特徴でも状況によって強みにも弱みにもなるため、対象と期間を明確にする。単独の人物が特定の年に発明したという帰属には歴史研究上の注意が必要である。","old_note":null,"new_note":null},{"id":"kb_548","title":"適応的計画","old_summary":"新たな情報や結果に応じて、行動の順序・方法・期限を更新する計画の立て方。目的と制約を共有しながら現実に合わせて修正する。","new_summary":"計画を固定的な予言ではなく、得られた情報に応じて更新する仮説として扱う考え。目的と制約を保ちつつ、手段、順序、期限を現実に合わせて修正する。","old_note":null,"new_note":null},{"id":"kb_285","title":"創発戦略","old_summary":"現場での行動と学習が積み重なり、その中から一貫した戦略が形づくられていくという考え方。実際に機能した選択のパターンに着目する。","new_summary":"最初から詳細に決めた計画ではなく、現場で得た情報と小さな成功から戦略を形成する考え方。","old_note":null,"new_note":null},{"id":"kb_931","title":"アブダクション","old_summary":"観察した事実を説明できる仮説を考え、有力な説明を導く推論。見つけた仮説は、追加の証拠や他の説明と照合して確かめる。","new_summary":"観察された事実を説明できる仮説を考え、候補の中から有力な説明を選ぶ推論。例えば遅延の原因を一つに決めず、設備、手順、情報の候補を比べる。新しい仮説を作る入口になるが、もっともらしい説明は真実の保証ではない。説明力、別の仮説、検証できる予測を照らし合わせる。","old_note":null,"new_note":null},{"id":"kb_933","title":"相関と因果の区別","old_summary":"二つの事柄が一緒に変わる関係と、一方の変化が他方を引き起こす関係を分けること。共通の原因や逆方向の因果も検討する。","new_summary":"二つの事柄が一緒に変化することと、一方を変えると他方が変わることは別である。売上と会議回数が同時に増えても、需要など別の要因が両方を動かしている可能性がある。逆方向の因果や交絡も考え、介入や研究設計を確認する。相関が役立たないという意味ではなく、予測と原因の主張を分ける。","old_note":null,"new_note":null},{"id":"kb_522","title":"統合型交渉","old_summary":"双方の優先順位の違いを活かし、条件の組み合わせによって総利益を増やす交渉。譲れる点と重視する点を交換し、合意の可能性を広げる。","new_summary":"限られた利益を奪い合うだけでなく、双方の優先順位の違いを見つけ、論点交換や条件設計によって総利益を増やす交渉。立場ではなく背後の利益を共有することが基礎になる。","old_note":null,"new_note":null},{"id":"kb_935","title":"人身攻撃の誤謬","old_summary":"発言者の人格や属性を攻撃することで、その主張への反論に代えてしまう推論の誤り。主張と根拠の結びつきを検討することが論点になる。","new_summary":"主張への反論の代わりに、発言者の人格や属性を攻撃して主張を退ける推論の誤り。嫌いな人の提案でも、根拠は独立に検討する必要がある。議論では人の評価と内容の評価を分ける。ただし証言の信用や利益相反が論点に直接関係する場合、その確認まで常に誤謬になるわけではない。","old_note":null,"new_note":null},{"id":"kb_495","title":"反復開発","old_summary":"小さく作り、試し、結果をもとに修正する周期を重ねて品質を高める開発方法。早く現実の反応を得て、誤った前提への投資を減らす。","new_summary":"完成形を一度で作るのではなく、小さく作り、利用・検証・修正を繰り返して品質を高める方法。早い段階で現実の情報を得られるため、誤った前提への大規模投資を防げる。","old_note":null,"new_note":null},{"id":"kb_545","title":"パレートの法則","old_summary":"成果や問題の大きな部分が、少数の原因に集中することがあるという経験則。影響の大きい要因を見つけ、優先順位をつける視点になる。","new_summary":"成果の大部分が少数の原因や活動から生じることが多い、という経験則。常に80対20になる数学法則ではなく、影響の偏りを見つける分析の入口として使う。","old_note":null,"new_note":null},{"id":"kb_599","title":"プレモーテム","old_summary":"計画が失敗した未来を想像し、その原因を事前に洗い出す手法。懸念を言語化して、対策や計画の修正につなげる。","new_summary":"計画が失敗した未来を先に仮定し、その原因を洗い出す意思決定手法。失敗を恐れるためではなく、言いにくい懸念を計画段階で表に出すために使う。","old_note":null,"new_note":null},{"id":"kb_938","title":"シンプソンのパラドックス","old_summary":"集団ごとに見られる割合の関係が、全体を合計すると逆転することがある現象。集団の構成比が違うと、全体平均が比較を誤らせる。","new_summary":"集団別では同じ方向に見える割合の関係が、集計すると逆転することがある現象。構成比や条件の違いを無視した全体平均は、比較を誤らせうる。部署や利用者層の内訳を確認する手掛かりになる。ただし分ければ常に正しいわけではなく、何を比較したいかと因果関係に応じて集計方法を選ぶ必要がある。","old_note":null,"new_note":null},{"id":"kb_486","title":"公正フレーミング","old_summary":"双方に適用できる基準・手続き・責任の公平さから、提案や配分を説明する方法。共通の基準が、条件への納得を支える。","new_summary":"提案や配分を、自分の都合ではなく、双方に適用できる基準・手続き・責任の公平さとして説明する方法。公正という言葉だけでなく、基準の一貫性が必要になる。","old_note":null,"new_note":null},{"id":"kb_778","title":"共有地の悲劇","old_summary":"共有の資源を各人が自分の短期利益のために使いすぎ、全体として資源を損なってしまう社会的ジレンマ。利用ルールや協力の仕組みが持続性を左右する。","new_summary":"共有資源を各人が短期利益のために使うと、全体として枯渇する社会的ジレンマ。所有権の一律私有化だけが解ではなく、地域の監視、ルール、信頼による統治も成立する。","old_note":null,"new_note":null},{"id":"kb_147","title":"利益立脚型交渉","old_summary":"要求の背後にある目的や必要を明らかにし、双方の利益を満たす案を探る交渉法。何を求めるかに加え、なぜそれが必要かを共有する。","new_summary":"表面的な要求ではなく、その背後にある目的やニーズを探り、双方の利益を満たす案をつくる交渉法。","old_note":null,"new_note":null}]'::jsonb; changed integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('theory-summary-editorial-rollback-20261019',0));
 lock table public.theories in share row exclusive mode;
 if exists(select 1 from jsonb_to_recordset(edits) x(id text,title text,old_summary text,old_note text) left join public.theories t on t.id=x.id
   where t.id is null or t.status<>'published' or t.title is distinct from x.title or t.summary is distinct from x.old_summary
   or (t.quotation->>'contextNote') is distinct from x.old_note) then
   raise exception 'Reviewed summary changed; back up and review current CMS content before applying.';
 end if;
 insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
 select 'summary-editorial-rollback-20261019','theories',t.id,to_jsonb(t) from public.theories t
 join jsonb_to_recordset(edits) x(id text) on t.id=x.id on conflict do nothing;
 update public.theories t set summary=x.new_summary,
   quotation=case when x.new_note is not null then jsonb_set(t.quotation,'{contextNote}',to_jsonb(x.new_note)) else t.quotation end,
   updated_at=now()
 from jsonb_to_recordset(edits) x(id text,new_summary text,new_note text) where t.id=x.id;
 get diagnostics changed = row_count;
 if changed<>jsonb_array_length(edits) then raise exception 'Summary update count mismatch';end if;
 if exists(select 1 from jsonb_to_recordset(edits) x(id text,new_summary text,new_note text) join public.theories t on t.id=x.id
   where t.summary is distinct from x.new_summary or t.quotation->>'contextNote' is distinct from x.new_note) then
   raise exception 'Canonical summary projection mismatch';
 end if;
end $edit$;
